window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["人物"]=[{"uid":"f75b4a85-1195-4795-bb42-4d7d52303414","title":"乐府","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["五更窗下簇妆台，已怕堂前阿母催。","满鸭香薰鹦鹉睡，隔帘灯照牡丹开。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"fe5870e3-82e9-4f97-9b2e-fb212a5afa96","title":"步虚词二首 二","author":"陈羽","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["楼殿层层阿母家，昆仑山顶驻红霞。","笙歌出见穆天子，相引笑看琪树花。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","楼","山"],"cats":{"人物":["母亲"]},"theme_conf":1.0},{"uid":"08155b8d-f4f2-486d-8d3d-b7260482feb1","title":"大觜乌","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["阳乌有二类，觜白者名慈。","求食哺慈母，因以此名之。","饮啄颇廉俭，音响亦柔雌。","百巢同一树，栖宿不复疑。","得食先反哺，一身常苦羸。","缘知五常性，飜被众禽欺。","其一觜大者，攫搏性贪痴。","有力强如鹘，有爪利如锥。","音响甚㕭嗗，潜通妖怪词。","受日余光庇，终天无死期。","翺翔富人屋，栖息屋前枝。","巫言此乌至，财产日丰宜。","主人一心惑，诱引不知疲。","转见乌来集，自言家转孳。","白鹤门外养，花鹰架上维。","专听乌喜怒，信受若神龟。","举家同此意，弹射不复施。","往往清池侧，却令鹓鹭随。","群乌饱粱肉，毛羽色泽滋。","远近恣所往，贪残无不为。","巢禽攫雏卵，廐马啄疮痍。","渗沥脂膏尽，凤皇那得知。","主人一朝病，争向屋檐窥。","呦鷕呼群𫛳，翩翻集怪鸱。","主人偏养者，啸聚最奔驰。","夜半仍惊噪，鸺鹠逐老狸。","主人病心怯，灯火夜深移。","左右虽无语，奄然皆泪垂。","平明天出日，阴魅走参差。","乌来屋檐上，又惑主人儿。","儿即当家业，玩好方爱奇。","占募能言鸟，置者许高赀。","陇树巢鹦鹉，言语好光仪。","美人倾心献，雕笼身自持。","求者临轩坐，置在白玉墀。","先问鸟中苦，便言乌若斯。","众乌齐搏铄，翠羽几离披。","远掷千余里，美人情亦衰。","举家惩此患，事乌逾昔时。","向言池上鹭，啄肉寝其皮。","夜漏天终晓，阴云风定吹。","况尔乌何者，数极不知危。","会结弥天网，尽取一无遗。","常令阿阁上，宛宛宿长离。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":[],"scene":["夜","鸟","楼"],"cats":{"抒情":["伤感","感恩"],"人物":["女子","母亲"]},"theme_conf":1.0},{"uid":"e8f030b1-9e72-4243-92b3-3c4ec8028354","title":"渔父歌 二","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["钓台渔父褐为裘，两两三三舴艋舟。","能纵櫂，惯乘流，长江白浪不曾忧。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"山水":["长江"],"人物":["父亲"]},"theme_conf":0.613},{"uid":"cp37eda4b1261602","title":"虞美人","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["曲阑干外天如水。","昨夜还曾倚。","初将明月比佳期。","长向月圆时候、望人归。","罗衣著破前香在。","旧意谁教改。","一春离恨懒调弦。","犹有两行闲泪、宝筝前。"],"theme":"爱情相思","theme2":["送别","闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.375},{"uid":"4a61c679-137e-47fb-a94c-dc41ff685ab9","title":"览柏中允兼子姪数人除官制词因述父子兄弟四美载歌丝纶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["纷然丧乱际，见此忠孝门。","蜀中寇亦甚，柏氏功弥存。","深诚补王室，戮力自元昆。","三止锦江沸，独清玉垒昏。","高名入竹帛，新渥照乾坤。","子弟先卒伍，芝兰叠玙璠。","同心注师律，洒血在戎轩。","丝纶实具载，绂冕已殊恩。","奉公举骨肉，诛叛经寒温。","金甲雪犹冻，朱旗尘不飜。","每闻战场说，歘激懦气奔。","圣主国多盗，贤臣官则尊。","方当节钺用，必绝祲沴根。","吾病日回首，云台谁再论。","作歌挹盛事，推毂期孤骞。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","雪"],"cats":{"抒情":["孤独"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.585},{"uid":"262d09ef-c986-4c06-81a4-9a75c6d83719","title":"岳阳楼别窦司直","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["洞庭九州间，厥大谁与让。","南汇群崖水，北注何奔放。","潴为七百里，吞纳各殊状。","自古澄不清，环混无归向。","炎风日搜搅，幽怪多冗长。","轩然大波起，宇宙隘而妨。","巍峩拔嵩华，腾踔较健壮。","声音一何宏，轰輵车万两。","犹疑帝轩辕，张乐就空旷。","蛟螭露笋簴，缟练吹组帐。","鬼神非人世，节奏颇跌踼。","阳施见夸丽，阴闭感凄怆。","朝过宜春口，极北缺隄障。","夜缆巴陵洲，丛芮才可傍。","星河尽涵泳，俯仰迷下上。","余澜怒不已，喧聒鸣瓮盎。","明登岳阳楼，辉焕朝日亮。","飞廉戢其威，清晏息纤纩。","泓澄湛凝绿，物影巧相况。","江豚时出戏，惊波忽荡瀁。","时当冬之孟，隙窍缩寒涨。","前临指近岸，侧坐眇难望。","涤濯神魂醒，幽怀舒以畅。","主人孩童旧，握手乍忻怅。","怜我窜逐归，相见得无恙。","开筵交履舃，烂漫倒家酿。","杯行无留停，高柱送清唱。","中盘进橙栗，投掷倾脯酱。","欢穷悲心生，婉娈不能忘。","念昔始读书，志欲干霸王。","屠龙破千金，为艺亦云亢。","爱才不择行，触事得谗谤。","前年出官由，此祸最无妄。","公卿采虚名，擢拜识天仗。","奸猜畏弹射，斥逐恣欺诳。","新恩移府庭，逼侧厕诸将。","于嗟苦驽缓，但惧失宜当。","追思南渡时，鱼腹甘所葬。","严程迫风帆，劈箭入高浪。","颠沈在须臾，忠鲠谁复谅。","生还真可喜，尅己自惩创。","庶从今日后，粗识得与丧。","事多改前好，趣有获新尚。","誓耕十亩田，不取万乘相。","细君知蚕织，稚子已能饷。","行当挂其冠，生死君一访。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":["慷慨","悲怆"],"scene":["楼","江"],"cats":{"抒情":["离别","伤感"],"天气":["星星"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.467},{"uid":"d5a61d84-8246-462a-beae-fea8dbc3c0df","title":"送孙德谕罢官往黔州","author":"苗发","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["中岁分符典石城，两朝趋陛谒承明。","阙下昨承归老疏，天南今切去乡情。","亲知握手三秋别，几杖扶身万里行。","伯道暮年无嗣子，欲将家事托门生。"],"theme":"送别","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["老师"]},"theme_conf":0.715},{"uid":"620e2d04-2cd5-4217-a8f0-64837017c7e4","title":"夜看美人宫棋","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宫棋布局不依经，黑白分明子数停。","巡拾玉沙天汉晓，犹残织女两三星。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","七夕"],"cats":{"天气":["星星"],"人物":["女子"],"节日":["七夕节"]},"theme_conf":0.62},{"uid":"2b9b6071-6dc8-4b04-949c-5350f23e4f9d","title":"和微之春日投简阳明洞天五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青阳行已半，白日坐将徂。","越国强仍大，稽城高且孤。","利饶盐煮海，名胜水澄湖。","牛斗天垂象，台明地展图。","瓌奇填市井，佳丽溢𬮱阇。","句践遗风霸，西施旧俗姝。","船头龙夭矫，桥脚兽睢盱。","乡味珍蟛蚏，时鲜贵鹧鸪。","语言诸夏异，衣服一方殊。","捣练蛾眉婢，鸣榔蛙角奴。","江清敌伊洛，山翠胜荆巫。","华表双栖鹤，联樯几点乌。","烟波分渡口，云树接城隅。","涧远松如画，洲平水似铺。","绿科秧早稻，紫笋折新芦。","暖蹋泥中藕，香寻石上蒲。","雨来萌尽达，雷后蛰全苏。","柳眼黄丝颣，花房绛蜡珠。","林风新竹折，野烧老桑枯。","带亸长枝蕙，钱穿短贯榆。","暄和生野菜，卑湿长街芜。","女浣纱相伴，儿烹鲤一呼。","山魈啼稚子，林狖挂山都。","产业论蚕蚁，孳生计鸭雏。","泉岩雪飘洒，苔壁锦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹庙径盘纡。","洞穴何因凿，星槎谁与刳。","石凹仙药臼，峰峭佛香炉。","去为投金简，来因挈玉壶。","贵仍招客宿，健未要人扶。","闻望贤丞相，仪形美丈夫。","前驱驻旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳凫。","学禅超后有，观妙造虚无。","髻里传僧宝，环中得道枢。","登楼诗八咏，置砚赋三都。","捧拥罗将绮，趋跄紫与朱。","庙谟藏稷卨，兵略贮孙吴。","令下三军整，风高四海趋。","千家得慈母，六郡事严姑。","重士过三哺，轻财抵一铢。","送觥歌宛转，嘲妓笑卢胡。","佐饮时炮鼈，蠲酲数鲙鲈。","醉乡虽咫尺，乐事亦须臾。","若不中贤圣，何由外智愚。","伊予一生志，我尔百年躯。","江上三千里，城中十二衢。","出多无伴侣，归只对妻孥。","白首青山约，抽身去得无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"欢愉","mood2":["孤寂"],"scene":["江","山","江南","舟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"天气":["太阳"],"人物":["母亲","儿童"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"61304178-6b16-4f98-87b2-4ad6bc98da98","title":"观公孙大娘弟子舞劒器行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔有佳人公孙氏，一舞劒气动四方。","观者如山色沮丧，天地为之久低昂。","㸌如羿射九日落，矫如群帝骖龙翔。","来如雷霆收震怒，罢如江海凝清光。","绛唇珠袖两寂莫，况有弟子传芬芳。","临颍美人在白帝，妙舞此曲神扬扬。","与余问答既有以，感时抚事增惋伤。","先帝侍女八千人，公孙劒器初第一。","五十年间似反掌，风尘倾动昏王室。","棃园子弟散如烟，女乐余姿映寒日。","金粟堆南木已拱，瞿唐石城草萧瑟。","玳筵急管曲复终，乐极哀来月东出。","老夫不知其所往，足茧荒山转愁疾。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":["绮丽","豪放"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":[],"cats":{"抒情":["伤感"],"人物":["女子","老师"]},"theme_conf":0.95},{"uid":"1419a84b-2586-444b-b987-5b874c580d0f","title":"杂歌谣辞 步虚词 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母种桃云海际，花落子成二千岁。","海风吹折最繁枝，跪捧琼盘献天帝。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":1.0},{"uid":"cd99fae2-e492-43a5-991d-5febb80ba51d","title":"宋中遇刘书记有别","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何代无秀士，高门生此才。","森然覩毛发，若见河山来。","几载困常调，一朝时运催。","白身谒明主，待诏登云台。","相逢梁宋间，与我醉蒿莱。","寒楚眇千里，雪天昼不开。","末路终离别，不能强悲哀。","男儿争富贵，劝尔莫迟廻。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雪"],"cats":{"抒情":["离别","伤感"],"人物":["老师"]},"theme_conf":1.0},{"uid":"c4501ca9-2069-4e6b-90c7-908f094f4fd1","title":"鼓吹曲辞 芳树","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢迢芳园树，列映清池曲。","对此伤人心，还如故时绿。","风条洒余霭，露叶承新旭。","佳人不再攀，下有往来躅。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["花","园林"],"cats":{"人物":["女子"]},"theme_conf":0.76},{"uid":"6bfd22e0-4623-4efc-9678-a4d436cde303","title":"江南弄","author":"芮挺章","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春江可怜事，最在美人家。","鹦鹉能言鸟，芙蓉巧笑花。","地衔金作埒，水抱玉为沙。","薄晚青丝骑，长鞭赴狭斜。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"山水":["江河"],"人物":["女子"]},"theme_conf":0.65},{"uid":"ea100f9a-3504-4a7d-844c-c23ba23f364b","title":"将适吴楚留别章使君留后兼幕府诸公得柳字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我来入蜀门，岁月亦已久。","岂惟长儿童，自觉成老丑。","常恐性坦率，失身为杯酒。","近辞痛饮徒，折节万夫后。","昔如纵壑鱼，今如丧家狗。","既无游方恋，行止复何有。","相逢半新故，取别随薄厚。","不意青草湖，扁舟落吾手。","眷眷章梓州，开筵俯高柳。","楼前出骑马，帐下罗宾友。","健儿簸红旗，此乐或难朽。","日车隐昆仑，鸟雀噪户牖。","波涛未足畏，三峡徒雷吼。","所忧盗贼多，重见衣冠走。","中原消息断，黄屋今安否。","终作适荆蛮，安排用庄叟。","随云拜东皇，挂席上南斗。","有使即寄书，无使长回首。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","酒","江南"],"cats":{"抒情":["离别"],"人物":["儿童"],"植物":["柳树"]},"theme_conf":0.715},{"uid":"8877c330-ce31-4a0b-a939-33b21e56b422","title":"行不由径","author":"俞简","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古人心有尚，乃是孔门生。","为计安贫乐，当从大道行。","讵应流远迹，方欲料前程。","捷径虽云易，长衢岂不平。","后来无枉路，先达擅前名。","一示遵途意，微衷益自精。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人物":["老师"]},"theme_conf":1.0},{"uid":"3bb3897a-7460-40d1-9ec3-b4738e3f20b4","title":"忆春日太液池亭候对","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宫莺报晓瑞烟开，三岛灵禽拂水回。","桥转彩虹当绮殿，舰浮花鹢近蓬莱。","草承香辇王孙长，桃艳仙颜阿母栽。","簪笔此时方侍从，却思金马笑邹枚。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["彩虹"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"bdd14fd6-3be3-4f4f-acb7-4c8080ee8c83","title":"赠衡岳隐禅师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["拥褐安居南岳头，白云高寺见衡州。","石窗湖水摇寒月，枫树猨声报夜秋。","讲席旧逢山鸟至，梵经初向竺僧求。","垂垂身老将传法，因下人间逐北游。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.82},{"uid":"805134d3-3d71-496b-a4ae-08e6871461ec","title":"咏虹","author":"苏味道","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纡余带星渚，窈窕架天浔。","空因壮士见，还共美人沈。","逸照含良玉，神花藻瑞金。","独留长劒彩，终负昔贤心。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"孤寂","mood2":["慷慨"],"scene":[],"cats":{"抒情":["孤独"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":1.0},{"uid":"2d7646fe-985e-4673-a554-61497dd86c8c","title":"同严给事闻唐昌观玉蘂近有仙过因成绝句二首 一","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千枝花里玉尘飞，阿母宫中见亦稀。","应共诸仙鬬百草，独来偷得一枝归。"],"theme":"游仙梦幻","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","怀古"],"人物":["母亲"]},"theme_conf":0.642},{"uid":"bc8adf47-d6ff-46f9-99a3-ee2833e075b7","title":"杂曲歌辞 昔昔盐 花飞桃李蹊","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远期难可托，桃李自依依。","花径无容迹，戎裘未下机。","随风开又落，度日扫还飞。","欲折枝枝赠，那知归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"56164c0c-6a83-4c3b-8f92-4c26a6e8e34e","title":"送从弟谒员外叔父回归义兴","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["异乡兄弟少，见尔自依然。","来酌林中酒，去耕湖上田。","何朝逢暑雨，几夜泊鱼烟。","余力当勤学，成名贵少年。"],"theme":"送别","theme2":["羁旅思乡","亲情"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"人物":["父亲"]},"theme_conf":0.296},{"uid":"ca8dc6f9-911f-4ae1-8f6a-0e6b374a5ede","title":"奉先刘少府新画山水障歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["堂上不合生枫树，怪底江山起烟雾。","闻君埽却赤县图，乘兴谴画沧洲趣。","画师亦无数，好手不可遇。","对此融心神，知君重毫素。","岂但祁岳与郑虔，笔迹远过杨契丹。","得非悬圃裂，无乃潇湘飜。","悄然坐我天姥下，耳边已似闻清猨。","反思前夜风雨急，乃是蒲城鬼神人。","元气淋漓障犹湿，真宰上诉天应泣。","野亭春还杂花远，渔翁暝蹋孤舟立。","沧浪水深青溟阔，攲岸侧岛秋毫末。","不见湘妃鼓瑟时，至今斑竹临江活。","刘侯天机精，爱画入骨髓。","自有两儿郎，挥洒亦莫比。","大儿聪明到，能添老树巅崖里。","小儿心孔开，貌得山僧及童子。","若耶溪，云门寺。","吾独胡为在泥滓，青鞵布韤从此始。"],"theme":"山水田园","theme2":["题画咏艺"],"style":"幽峭","style2":["清新","沉郁"],"mood":"孤寂","mood2":["相思","悲怆"],"scene":["山","秋","江","雨"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.468},{"uid":"6d46b6ce-5c89-4a0b-b496-c1718293fa90","title":"赋得北方有佳人","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["由来称独立，本自号倾城。","柳叶眉间发，桃花脸上生。","腕摇金钏响，步转玉环鸣。","纤腰宜宝袜，红衫艳织成。","悬知一顾重，别觉舞腰轻。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"人物":["女子"]},"theme_conf":0.476},{"uid":"7e4ea5d5-bb63-41ce-81c1-44716ae9dcbf","title":"杂歌谣辞 渔父歌 五","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青草湖中月正圆，巴陵渔父棹歌连。","钓车子，掘头船，乐在风波不用仙。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["舟"],"cats":{"人物":["父亲"]},"theme_conf":0.613},{"uid":"5bc37c7b-af6e-4a86-9d48-c558c25293a8","title":"墙阴歌","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["白日左右浮天潢，朝晡影入东西墙。","昔为儿童在阴戏，当时意小觉日长。","东邻侯家吹笙簧，随阴促促移象床。","西邻田舍乏糟糠，就影汲汲舂黄粱。","因思九州四海外，家家只占墙阴内。","莫言墙阴数尺间，老却主人如等闲。","君看眼前光阴促，中心莫学太行山。"],"theme":"哲理悟道","theme2":[],"style":"豪放","style2":["旷达"],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["儿童"],"人生":["时光"]},"theme_conf":0.86},{"uid":"d8592aae-e77c-4393-91b5-30a4db50c8e3","title":"上巳日陪齐相公花楼宴","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["钟陵暮春月，飞观延群英。","晨霞耀中轩，满席罗金琼。","持杯凝远睇，触物结幽情。","树色参差绿，湖光潋滟明。","礼卑瞻绛帐，恩浃厕华缨。","徒记山阴兴，祓禊乃为荣。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"人物":["老师"]},"theme_conf":0.72},{"uid":"82d09cba-94f5-40ba-9435-ec83e2c5ad89","title":"游子","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["萱草生堂堦，游子行天涯。","慈亲倚堂门，不见萱草花。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["母亲"]},"theme_conf":0.787},{"uid":"1558a170-9f05-4a1a-b907-b9f6061f4772","title":"饯济阴梁明府各探一物得荷叶","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荷叶生幽渚，芳华信在兹。","朝朝空此地，采采欲因谁。","但恐星霜改，还将蒲稗衰。","怀君美人别，聊以赠心期。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"四季":["夏天"],"人物":["女子"],"人生":["青春"],"植物":["荷花","叶子"]},"theme_conf":0.799},{"uid":"6fac0cea-b4ee-419b-9802-786d508141f9","title":"冬行三首 一","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虫豸腊月皆在蛰，吾独何乃劳其形。","小大无由知天命，但怪守道不得宁。","老母妻子一挥手，涕下便作千里行。","自顾不及遭霜叶，旦夕保得同飘零。","达生何足云，偶然苦乐经其身。","古来尧孔与桀跖，善恶何补如今人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["欢愉"],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"26cbab92-a321-44e6-842b-13acc9749fc0","title":"羌村 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["群鸡正乱叫，客至鸡鬬争。","驱鸡上树木，始闻叩柴荆。","父老四五人，问我久远行。","手中各有携，倾榼浊复清。","苦辞酒味薄，黍地无人耕。","兵革既未息，儿童尽东征。","请为父老歌，艰难块深情。","歌罢仰天叹，四座泪纵横。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.379},{"uid":"cd8c3590-e097-4289-bcda-ad852ed095ab","title":"杂曲歌辞 悲哉行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["促促晨复昏，死生同一源。","贵年不惧老，贱老伤久存。","朗朗哭前歌，绛旌引幽魂。","来为千金子，去卧百草根。","黄土塞生路，悲风送回辕。","金鞍旧良马，四顾不出门。","生结千岁念，荣及百代孙。","黄金买性命，白刃讐一言。","宁知北山上，松柏侵田园。"],"theme":"边塞征战","theme2":["送别"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人物":["老师"],"生活":["田园","边塞"]},"theme_conf":0.516},{"uid":"75af1049-35a3-42ae-bffd-90089bf3ef27","title":"游仙二首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蛾眉新画觉婵娟，鬬走将花阿母边。","仙曲教成慵不理，玉阶相簇打金钱。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["中秋"],"cats":{"人物":["母亲"],"节日":["中秋节"]},"theme_conf":0.669},{"uid":"b3869955-7214-4042-942d-a22afb8575eb","title":"杂嘲二首 一","author":"崔涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["二年不到宋家东，阿母深居僻巷中。","含泪向人羞不语，琵琶弦断倚屏风。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"a6718251-5934-4db9-ae50-edf26f8b0ea8","title":"对菊","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["九日不出门，十日见黄菊。","灼灼尚繁英，美人无消息。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"人物":["女子"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"a833a7e3-13da-49f1-83eb-4b3db1dab38d","title":"赋虞书歌","author":"贾躭","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["众书之中虞书巧，体法自然归大道。","不同怀素只攻颠，岂类张芝惟创草。","形势素，筋骨老，父子君臣相揖抱。","孤青似竹更飕飔，阔白如波长浩渺。","能方正，不隳倒，功夫未至难寻奥。","须知孔子庙堂碑，便是青箱中至宝。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","怀古"],"人物":["父亲"]},"theme_conf":0.65},{"uid":"0c8565cc-bd2e-4b5a-87e3-00119062da17","title":"农父","author":"张碧","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["运锄耕𣃁侵星起，陇亩丰盈满家喜。","到头禾黍属他人，不知何处抛妻子。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人物":["父亲"],"生活":["田园"]},"theme_conf":0.713},{"uid":"152344f5-238d-42e9-9b7e-3476310e1b35","title":"杂曲歌辞 前有一尊酒行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春风东来忽相过，金尊绿酒生微波。","落花纷纷稍觉多，美人欲醉朱颜酡。","青轩桃李能几何？流光欺人忽蹉跎。","君起舞，日西夕，当年意气不肯倾，白发如丝叹何益。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["酒"],"cats":{"人物":["女子"],"食物":["写酒"]},"theme_conf":0.93},{"uid":"11964ccb-20f2-4a42-9ae2-d6a3e11ef7dc","title":"登刘宾客高斋","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["能以功成疎宠位，不将心赏负云霞。","林间客散孙弘阁，城上山宜绮季家。","蝴蝶晴连池岸草，黄鹂晚出柳园花。","日陪鲤也趋文苑，谁道门生隔绛纱。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["园林"],"cats":{"抒情":["思乡"],"天气":["写云"],"人物":["老师"]},"theme_conf":0.581},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"2693b5ba-1e9a-4d8b-a415-dfc484c9efa9","title":"正乐府十篇 农父谣","author":"皮日休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["农父冤辛苦，向我述其情。","难将一人农，可备十人征。","如何江淮粟，挽漕输咸京。","黄河水如电，一半沈与倾。","均输利其事，职司安敢评。","三川岂不农，三辅岂不耕。","奚不车其粟，用以供天兵。","美哉农父言，何计达王程。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"山水":["黄河"],"人物":["父亲"]},"theme_conf":0.533},{"uid":"4e9ac5c4-8f12-40f3-acce-39567d0bdfc5","title":"县斋有怀","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少小尚奇伟，平生足悲咤。","犹嫌子夏儒，肯学樊迟稼。","事业窥臯稷，文章蔑曹谢。","濯缨起江湖，缀佩杂兰麝。","悠悠指长道，去去策高驾。","谁为倾国媒，自许连城价。","初随计吏贡，屡入泽宫射。","虽免十上劳，何能一战霸。","人情忌殊异，世路多权诈。","蹉跎颜遂低，摧折气愈下。","冶长信非罪，侯生或遭骂。","怀书出皇都，衔泪渡清灞。","身将老寂寞，志欲死闲暇。","朝食不盈肠，冬衣才掩髂。","军书既频召，戎马乃连跨。","大梁从相公，彭城赴仆射。","弓箭围狐兔，丝竹罗酒{炙火=肉}。","两府变荒凉，三年就休假。","求官去东洛，犯雪过西华。","尘埃紫陌春，风雨灵台夜。","名声荷朋友，援引乏姻娅。","虽陪彤庭臣，讵纵青冥靶。","寒空耸危阙，晓色曜修架。","捐躯辰在丁，铩翮时方蜡。","投荒诚职分，领邑幸宽赦。","湖波翻日车，岭石坼天罅。","毒雾恒熏昼，炎风每烧夏。","雷威固已加，飓势仍相借。","气象杳难测，声音吁可怕。","夷言听未惯，越俗循犹乍。","指摘两憎嫌，睢盱互猜讶。","祗缘恩未报，岂谓生足藉。","嗣皇新继明，率土日流化。","惟思涤瑕垢，长去事桑柘。","𣃁嵩开云扃，压颍抗风榭。","禾麦种满地，梨枣栽绕舍。","儿童稍长成，雀鼠得驱吓。","官租日输纳，村酒时邀迓。","闲爱老农愚，归弄小女姹。","如今便可尔，何用毕婚嫁。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["夏","冬","江"],"cats":{"抒情":["伤感","孤独","爱国"],"四季":["夏天","冬天"],"人物":["儿童"]},"theme_conf":0.494},{"uid":"cpd98ebb7b2c6b91","title":"蓦山溪","author":"曹组","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洗妆真态，不作铅华御。","竹外一枝斜，想佳人、天寒日暮。","黄昏小院，无处著清香，风细细，雪垂垂，何况江头路。","月边疏影，梦到消魂处。","结子欲黄时，又须著、廉纤细雨。","孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨","花","山","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"00378596-0b01-448f-bb44-617317621bfe","title":"中和初童谣","author":"不详","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["黄巢走，泰山东，死在翁家翁。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"山水":["泰山"],"人物":["儿童"]},"theme_conf":0.82},{"uid":"7896c24e-7c04-4e75-9bec-4867baf47de4","title":"和高仆射罢节度让尚书授少保分司喜遂游山水之作","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["𫏐辞八座罢双旌，便作登山临水行。","能以忠贞酬重任，不将富贵碍高情。","朱门出去簪缨从，绛帐归来歌吹迎。","鞍辔闹装光满马，何人信道是书生。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"人物":["老师"]},"theme_conf":0.484},{"uid":"1e3e1062-ee73-4c2e-9fcf-9554fae22e1e","title":"杂歌谣辞 渔父歌","author":"和凝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白芷汀寒立鹭[鸶]，苹风轻翦浪花时。","烟幂幂，日迟迟，香引芙蓉惹钓丝。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["花","江"],"cats":{"人物":["父亲"]},"theme_conf":0.645},{"uid":"96314951-671b-423f-a172-4f10ec08a6f2","title":"初秋夜坐赠吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["稍稍雨侵竹，翻翻鹊惊丛。","美人隔湘浦，一夕生秋风。","积雾杳难极，沧波浩无穷。","相思岂云远，即席莫与同。","若人抱奇音，朱弦緪枯桐。","清商激西颢，泛滟凌长空。","自得本无作，天成谅非功。","希声閟大朴，聋俗何由聪。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":0.95},{"uid":"6b91be50-04b7-4afd-a8cd-fd519f6913e2","title":"送冷朝阳及第东归江宁","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高第由佳句，诸生似者稀。","长安带酒别，建业候潮归。","稚子欢迎櫂，隣人为扫扉。","含情过旧浦，鸥鸟亦依依。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"天气":["太阳"],"人物":["儿童"]},"theme_conf":0.563},{"uid":"beee5922-6237-4c9a-af25-43a4cb4274e6","title":"送从弟永任饶州录事参军","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一官万里向千溪，水宿山行鱼浦西。","日晚长烟高岸近，天寒积雪远峰低。","芦花渚里鸿相呌，苦竹丛边猨暗啼。","闻道慈亲倚门待，到时兰叶正萋萋。"],"theme":"送别","theme2":["边塞征战","山水田园"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山","雪"],"cats":{"天气":["写雪"],"人物":["母亲"]},"theme_conf":0.403},{"uid":"cp63eba452c87667","title":"风入松","author":"俞国宝","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一春长费买花钱。","日日醉花边。","玉骢惯识西湖路，骄嘶过、沽酒垆前。","红杏香中箫鼓，绿杨影里秋千。","暖风十里丽人天。","花压髻云偏。","画船载取春归去，馀情寄、湖水湖烟。","明日重扶残醉，来寻陌上花钿。"],"theme":"山水田园","theme2":["送别","闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"恬淡","mood2":[],"scene":["酒","花","春","江南"],"cats":{"四季":["春天"],"山水":["西湖"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.393},{"uid":"a7a08144-c10f-44ef-8558-7064cc123c68","title":"孟夫子生生亭赋","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["玉川子沿孟冬之寒流兮，辍櫂上登生生亭。","夫子何之兮，面逐云没兮南行。","百川注海而心不写兮，落日千里凝寒精。","予日衰期人生之世斯已矣，爰为今日犹犹岐路之心生。","悲夫！南国风涛，鱼龙畜伏。","予小子戆朴，必不能济夫子欲。","嗟自慙承夫子而不失予兮，传古道甚分明。","予且广孤目遐賷于天壤兮，庶得外尽万物变化之幽情。","然后慙愧而来归兮，大息吾躬于夫子之亭。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["悲怆","惆怅"],"scene":["楼","冬"],"cats":{"抒情":["伤感","孤独"],"四季":["冬天"],"人物":["老师"]},"theme_conf":0.72},{"uid":"4bd7acac-92da-4afa-b14d-010bb5e9da52","title":"杂歌","author":"李端","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉水至清泥则浊，松枝至坚萝则弱。","十三女儿事他家，颜色如花终索寞。","兰生当门燕巢幙，兰芽未吐燕泥落。","为姑偏忌诸嫂良，作妇翻嫌壻家恶。","人生照镜须自知，无盐何用妬西施。","秦庭野鹿忽为马，巧伪乱真君试思。","伯奇掇蜂贤父逐，曾参杀人慈母疑。","酒沽千日人不醉，琴弄一弦心已悲。","常闻善交无尔汝，谗口甚甘良药苦。","山鸡锦翼岂凤凰，陇鸟人言止鹦鹉。","向栩非才徒隐灶，田文有命那关户。","犀烛江行见鬼神，木人登席呈歌舞。","乐生东去终居赵，阳虎北辕飜适楚。","世间反复不易陈，缄此贻君泪如雨。"],"theme":"亲情","theme2":["闲适隐逸"],"style":"幽峭","style2":["清新"],"mood":"愁怨","mood2":["悲怆"],"scene":["酒","鸟"],"cats":{"抒情":["伤感","感恩"],"人物":["母亲"]},"theme_conf":0.561},{"uid":"86d084a1-6ccd-49a1-8757-cebc29ef13e8","title":"陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日放船好，轻风生浪迟。","竹深留客处，荷净纳凉时。","公子调冰水，佳人雪藕丝。","片云头上黑，应是雨催诗。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"b244fa50-b7bf-4901-b030-464f18c1c455","title":"送杨将军","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一身良将后，万里讨乌孙。","落日边陲静，秋风鼓角喧。","远山当碛路，茂草向营门。","生死酬恩宠，功名岂敢论。"],"theme":"边塞征战","theme2":["送别"],"style":"冲淡","style2":["豪放"],"mood":"恬淡","mood2":["悲怆","慷慨"],"scene":["秋","山"],"cats":{"四季":["秋天"],"人物":["老师"]},"theme_conf":0.528},{"uid":"6629f32a-e163-4400-8684-a459c3b6bb52","title":"送崔秀才赴上元兼省叔父","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒塘敛暮雪，腊鼓迎春早。","匹马五城人，重裘千里道。","淮山轻露湿，江树狂风扫。","楚县久酝𬪩，扬州百花好。","练湖东望接云阳，女市西游入建康。","行乐远夸红布旆，风流近赌紫香囊。","诗家行辈如君少，极目苦心怀谢朓。","烟开日上板桥南，吴岫青青出林表。"],"theme":"送别","theme2":["节令风俗"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["元宵","山"],"cats":{"天气":["写风"],"人物":["父亲"],"生活":["写桥"],"节日":["元宵节"]},"theme_conf":0.49},{"uid":"0ba4d426-8dd5-4a77-9566-98d96222417f","title":"相和歌辞 江南曲","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["美人何荡漾，湖上风月长。","玉手欲有赠，裴回双鸣珰。","歌声随渌水，怨色起朝阳。","日暮还家望，云波横洞房。"],"theme":"爱情相思","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"天气":["太阳"],"人物":["女子"]},"theme_conf":0.85},{"uid":"39fdb908-0035-476f-b871-31447e4f7af1","title":"奉和元丞侍从游南城别业","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂朱领孙子，从宴在池塘。","献寿回龟顾，和羹跃鲤香。","高松先草晚，平石助泉凉。","余橘期相及，门生有陆郎。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["离别"],"人物":["老师"]},"theme_conf":0.93},{"uid":"6d8b0386-c539-45d8-8d63-f7d90c74f21c","title":"哭刘夫子","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近问南州客，云亡已数春。","痛心曾受业，追服恨无亲。","孀妇归乡里，书斋属四邻。","不知经乱后，奠祭有何人。"],"theme":"悼亡挽歌","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","悼亡"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.97},{"uid":"25eeaa0b-dad0-4164-bb62-1896bdb82443","title":"詶国子崔博士立之见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["健笔高科早绝伦，后来无不揖芳尘。","遍看今日乘轩客，多是昔年呈卷人。","胄子执经瞻讲坐，郎官共食接华茵。","烦君远寄相思曲，慰问天南一逐臣。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["老师"]},"theme_conf":0.98},{"uid":"0d8d840d-1f94-44da-9b52-18a01cf8ed82","title":"下第日书情寄上叔父","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["微才空觉滞京师，末学曾为叔父知。","雪里题诗偏见赏，林间饮酒独令随。","游客尽伤春色老，贫居还惜暮阴移。","欲归江海寻山去，愿报何人得桂枝。"],"theme":"寄赠酬答","theme2":["亲情"],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","酒","春","江","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.8},{"uid":"d3ab98da-082d-4117-98e1-79bc8c2635ed","title":"赋得樱桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["华林满芳景，洛阳徧阳春。","朱颜含远日，翠色影长津。","乔柯啭娇鸟，低枝映美人。","昔作园中实，今来席上珍。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春","园林"],"cats":{"四季":["春天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"a335f6c4-e9df-47d5-879d-9ebd3c1baf5c","title":"北征","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["皇帝二载秋，闰八月初吉。","杜子将北征，苍茫问家室。","维时遭艰虞，朝野少暇日。","顾慙恩私被，诏许归蓬荜。","拜辞诣阙下，怵惕久未出。","虽乏谏诤姿，恐君有遗失。","君诚中兴主，经纬固密勿。","东胡反未已，臣甫愤所切。","挥涕恋行在，道途犹恍惚。","乾坤含疮痍，忧虞何时毕。","靡靡逾阡陌，人烟眇萧瑟。","所遇多被伤，呻吟更流血。","回首凤翔县，旌旗晚明灭。","前登寒山重，屡得饮马窟。","邠郊入地底，泾水中荡潏。","猛虎立我前，苍崖吼时裂。","菊垂今秋花，石戴古车辙。","青云动高兴，幽事亦可悦。","山果多琐细，罗生杂橡栗。","或红如丹砂，或黑如点漆。","雨露之所濡，甘苦齐结实。","缅思桃源内，益叹身世拙。","坡陀望鄜畤，岩谷互出没。","我行已水滨，我仆犹木末。","鸱鸟鸣黄桑，野鼠拱乱穴。","夜深经战场，寒月照白骨。","潼关百万师，往者散何卒。","遂令半秦民，残害为异物。","况我堕胡尘，及归尽华发。","经年至茅屋，妻子衣百结。","恸哭松声回，悲泉共幽咽。","平生所娇儿，颜色白胜雪。","见耶背面啼，垢腻脚不韤。","床前两小女，补绽才过膝。","海图坼波涛，旧绣移曲折。","天吴及紫凤，颠倒在裋褐。","老夫情怀恶，呕泄卧数日。","那无囊中帛，救汝寒凛栗。","粉黛亦解苞，衾裯稍罗列。","瘦妻面复光，痴女头自栉。","学母无不为，晓妆随手抹。","移时施朱铅，狼藉画眉阔。","生还对童穉，似欲忘饥渴。","问事竞挽须，谁能即嗔喝。","飜思在贼愁，甘受杂乱聒。","新归且慰意，生理焉能说。","至尊尚蒙尘，几日休练卒。","仰观天色改，坐觉祅气豁。","阴风西北来，惨澹随回鹘。","其王愿助顺，其俗善驰突。","送兵五千人，驱马一万匹。","此辈少为贵，四方服勇决。","所用皆鹰腾，破敌过箭疾。","圣心颇虚伫，时议气欲夺。","伊洛指掌收，西京不足拔。","官军请深入，蓄锐何俱发。","此举开青徐，旋瞻略恒碣。","昊天积霜露，正气有肃杀。","祸转亡胡岁，势成擒胡月。","胡命其能久，皇纲未宜绝。","忆昨狼狈初，事与古先别。","奸臣竟葅醢，同恶随荡析。","不闻夏殷衰，中自诛褒妲。","周汉获再兴，宣光果明哲。","桓桓陈将军，仗钺奋忠烈。","微尔人尽非，于今国犹活。","凄凉大同殿，寂寞白兽闼。","都人望翠华，佳气向金阙。","园陵固有神，埽洒数不缺。","煌煌太宗业，树立甚宏达。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":["绮丽","悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["秋","山","夜","夏","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天","秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"6326d175-7980-4cbc-9237-62120d12a482","title":"献荥阳公诗五十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑驿骑翩翩，丘门子弟贤。","文翁开学日，正礼骋途年。","骏骨黄金买，英髦绛帐延。","趋风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","凤攒题字扇，鱼落讲经筵。","盛气河包济，贞姿岳柱天。","臯夔当五百，邹鲁重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗缀夜珠联。","逸礼多心匠，焚书旧口传。","陈遵修尺牍，阮瑀让飞牋。","中的颜初启，抽毫踵未旋。","森罗万木合，属对百花全。","词海跳波涌，文星拂坐悬。","戴冯遥避席，祖逖后施鞭。","西蜀凌云赋，东阳咏月篇。","劲芟鼇足断，精贯虱心穿。","浩汗神弥王，鹞飏兴欲仙。","冰壶通皓雪，绮树眇晴烟。","驱驾雷霆走，铺陈锦绣鲜。","情机登穾奥，流韵溢山川。","墨客膺潜服，谈宾膝误前。","张鳞定摧败，折角反矜怜。","句句推琼玉，声声播管弦。","纤新撩造化，澒洞斡陶甄。","卫磬琤鍧极，齐竽僭滥偏。","空虚慙炙輠，点窜许怀铅。","惫色秋来草，哀吟雨后蝉。","自伤魂惨沮，何暇思幽玄。","喜到樽罍侧，愁亲几案边。","菁华知竭矣，胏腑尚求旃。","抵滞浑成醉，徘徊转慕膻。","老叹才渐少，闲苦病相煎。","瓦砾难追琢，刍荛分弃捐。","漫劳成恳恳，那得美娟娟。","拙劣仍非速，迂愚且异专。","移时停笔砚，挥景乏戈鋋。","仪舌忻犹在，舒帷誓不褰。","会将连献楚，深耻谬游燕。","蒲有临书叶，韦充读易编。","沙须披见宝，经拟带耕田。","入雾长期闰，持朱本望研。","轮辕呈曲直，凿枘取方圆。","呼吸宁徒尔，沾濡岂浪然。","过箫资响亮，随水涨沦涟。","惜日看圭短，偷光恨壁坚。","勤勤雕朽木，细细导蒙泉。","传癖今应甚，头风昨已痊。","丹青公旧物，一为变蚩妍。"],"theme":"应制干谒","theme2":["山水田园","应制干谒","羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["酒","雪","冬","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.98},{"uid":"9e10394a-b2cf-4f84-a07c-2b1103966824","title":"秋野五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["身许麒膦画，年衰鸳鹭群。","大江秋易盛，空峡夜多闻。","径隐千重石，帆留一片云。","儿童解蛮语，不必作参军。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"山水":["长江"],"人物":["儿童"]},"theme_conf":0.72},{"uid":"1dae0963-7101-4cf3-a045-1c0607adc419","title":"渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白发沧浪上，全忘是与非。","秋潭垂钓去，夜月叩船归。","烟影侵芦岸，潮痕在竹扉。","终年狎鸥鸟，来去且无机。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","夜","月","舟","江"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.737},{"uid":"452ca2e5-a3f8-4dd1-b262-6ba2af5f3ea3","title":"杂曲歌辞 拜新月","author":"吉中孚妻张氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["拜新月，拜月出堂前。","暗魄深笼桂，虚弓未引弦。","拜新月，拜月妆楼上。","鸾镜未安台，蛾眉已相向。","拜新月，拜月不胜情，庭前风露清。","月临人自老，望月更长生。","东家阿母亦拜月，一拜一悲声断绝。","昔年拜月逞容仪，如今拜月双泪垂。","回看众女拜新月，却忆红闺年少时。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["月"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"3b5db620-1964-4674-a01d-ad70ba3ebd2a","title":"咏怀古迹五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["群山万壑赴荆门，生长明妃尚有村。","一去紫台连朔漠，独留青冢向黄昏。","画图省识春风面，环佩空归月夜魂。","千载琵琶作胡语，分明怨恨曲中论。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["塞外","山","夜"],"cats":{"抒情":["孤独","怀古"],"人物":["老师"]},"theme_conf":0.549},{"uid":"afc80a09-19c1-466c-aeda-9a90b0b0ff3f","title":"商山麻涧","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["云光岚彩四面合，柔柔垂柳十余家。","雉飞鹿过芳草远，牛巷鸡埘春日斜。","秀眉老父对罇酒，蒨袖女儿簪野花。","征车自念尘土计，惆怅溪边书细沙。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["恬淡"],"scene":["山","花","春","酒"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.706},{"uid":"791da1d7-ca84-47fa-aa2a-fda1635a2f79","title":"游义兴寺寄上李逢吉相公","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["柳营无事诣莲宫，步步犹疑是梦中。","劳役徒为万夫长，闲游曾与二人同。","凤鸾飞去仙巢在，龙象潜来讲席空。","松下花飞频伫立，一心千里忆梁公。"],"theme":"寄赠酬答","theme2":["哲理悟道","应制干谒"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉","恬淡"],"scene":[],"cats":{"抒情":["思念"],"人物":["老师"]},"theme_conf":0.88},{"uid":"e283ac05-0ee6-4342-b972-af263c1e2405","title":"尊师是桃源黄先生传法弟子常见尊师称先师灵迹今重赋此诗兼寄题黄先生旧馆","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["后学方成市，吾师又上宾。","洞天应不夜，源树秪如春。","棋客留童子，山精避直神。","无因握石髓，及与养生人。"],"theme":"佛道禅颂","theme2":["送别","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","夜","山"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"f3a62c39-2698-4d68-842f-a9ff595faa85","title":"题缑山王子晋庙","author":"郑畋","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有昔灵王子，吹笙溯泬㵳。","六宫攀不住，三岛去相招。","亡国原陵古，宾天岁月遥。","无蹊窥海曲，有庙访山椒。","石帐龙蛇拱，云栊彩翠销。","露坛装琬琰，真像写松乔。","珠馆青童宴，琳宫阿母朝。","气舆仙女侍，天马吏兵调。","湘妓红丝瑟，秦郎白管箫。","西城要绰约，南岳命娇娆。","句曲觞金洞，天台啸石桥。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元宝箓饶。","雾垂鸦翅发，冰束虎章腰。","鹤驭争衔箭，龙妃合献绡。","衣从星渚浣，丹就日宫烧。","物外花尝满，人间叶自凋。","望台悲汉戾，阅水笑梁昭。","古殿香残炧，荒堦柳长条。","几曾期七日，无复降重霄。","嵩岭连天汉，伊澜入海潮。","何由得真诀，使我珮环飘。"],"theme":"山水田园","theme2":["咏物","游仙梦幻"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["山"],"cats":{"抒情":["伤感"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.418},{"uid":"2c1d7719-593f-489d-ae78-3e1e34a66412","title":"鼓吹曲辞 将进酒","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["将进酒，将进酒。","酒中有毒酖主父，言之主父伤主母。","母为妾地父妾天，仰天俯地不忍言。","佯为僵踣主父前，主父不知加妾鞭。","旁人知妾为主说，主将泪洗鞭头血。","推摧主母牵下堂，扶妾遣升堂上床。","将进酒，酒中无毒令主寿。","愿主回思归主母，遣妾如此事主父。","妾为此事人偶知，自慙不密方自悲。","主今颠倒安置妾，贪天僭地谁不为。"],"theme":"讽喻刺世","theme2":["闺情宫怨","羁旅思乡","闲适隐逸"],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡","伤感","闺怨"],"人物":["父亲"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"22923091-18da-429d-9ef1-6b367fd74b1a","title":"杂曲歌辞 游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"da625d4b-a775-4c5e-9860-4bfe89e481ce","title":"秦州杂诗二十首 十六","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东柯好崖谷，不与众峰群。","落日邀双鸟，晴天养片云。","野人矜险绝，水竹会平分。","采药吾将老，儿童未遣闻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人物":["儿童"]},"theme_conf":1.0},{"uid":"0222bb09-1f03-473b-b3d7-bd41709a2643","title":"朱陈村","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["徐州古丰县，有村曰朱陈。","去县百余里，桑麻青氛氲。","机梭声札札，牛驴走纭纭。","女汲涧中水，男采山上薪。","县远官事少，山深人俗淳。","有财不行商，有丁不入军。","家家守村业，头白不出门。","生为村之民，死为村之尘。","田中老与幼，相见何欣欣。","一村唯两姓，世世为婚姻。","亲疎居有族，少长游有群。","黄鸡与白酒，欢会不隔旬。","生者不远别，嫁娶先近邻。","死者不远葬，坟墓多绕村。","既安生与死，不苦形与神。","所以多寿考，往往见玄孙。","我生礼义乡，少小孤且贫。","徒学辨是非，祗自取辛勤。","世法贵名教，士人重冠婚。","以此自桎梏，信为大谬人。","十岁解读书，十五能属文。","二十举秀才，三十为谏臣。","下有妻子累，上有君亲恩。","承家与事国，望此不肖身。","忆昨旅游初，迨今十五春。","孤舟三适楚，羸马四经秦。","昼行有饥色，夜寝无安魂。","东西不暂住，来往若浮云。","离乱失故乡，骨肉多散分。","江南与江北，各有平生亲。","平生终日别，逝者隔年闻。","朝忧卧至暮，夕哭坐达晨。","悲火烧心曲，愁霜侵鬓根。","一生苦如此，长羡村中民。"],"theme":"山水田园","theme2":["羁旅思乡","悼亡挽歌"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思乡","伤感","悼亡"],"人物":["老师"],"人生":["读书"],"生活":["乡村","田园"]},"theme_conf":0.301},{"uid":"e76a9e8e-c640-40b3-bf3d-dc0ca2985fe4","title":"答寄芙蓉冠子","author":"王建","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一学芙蓉叶，初开映水幽。","虽经小儿手，不称老夫头。","枕上眠常戴，风前醉恐柔。","明年有闺阁，此样必难求。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","楼"],"cats":{"人物":["儿童"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"8f5beb73-918d-41e2-a864-05145271987d","title":"戏赠张炼师","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月帔飘飖摘杏花，相邀洞口劝流霞。","半酣乍奏云和曲，疑是龟山阿母家。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["月","山"],"cats":{"人物":["母亲"]},"theme_conf":0.72},{"uid":"0be9008f-d175-47f6-aa53-87fce8d020fa","title":"渔父歌","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曲岸深潭一山叟，驻眼看钩不移手。","世人欲得知姓名，良久问他不开口。","笋皮笠子荷叶衣，心无所营守钓矶。","料得孤舟无定止，日暮持竿何处归。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","山"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.545},{"uid":"a7bd6a97-1713-4cfc-bb5d-0fb0c6b7cca3","title":"渔父","author":"汪遵","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["棹月眠流处处通，绿蓑苇带混元风。","灵均说尽孤高事，全与逍遥意不同。"],"theme":"山水田园","theme2":["亲情"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","月"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.533},{"uid":"204e287b-8194-4c2d-808b-11cc260412ae","title":"渭川田家","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["斜阳照墟落，穷巷牛羊归。","野老念牧童，倚杖候荆扉。","雉雊麦苗秀，蚕眠桑叶稀。","田夫荷锄至，相见语依依。","即此羡闲逸，怅然吟式微。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["儿童"],"生活":["田园"]},"theme_conf":0.429},{"uid":"18a2193c-1bd7-4426-b17f-d02a8a4aec1b","title":"莺莺歌","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伯劳飞迟燕飞疾，垂杨绽金花笑日。","绿窗娇女字莺莺，金雀娅鬟年十七。","黄姑上天阿母在，寂莫霜姿素莲质。","门掩重关萧寺中，芳草花时不曾出。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"四季":["春天"],"人物":["母亲"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"0f9dd333-5f18-478b-8b18-53ed1bf06e91","title":"秋夜听严绅巴童唱竹枝歌","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巴人远从荆山客，回首荆山楚云隔。","思归夜唱竹枝歌，庭槐叶落秋风多。","曲中历历叙乡土，乡思绵绵楚词古。","身骑吴牛不畏虎，手提蓑笠欺风雨。","猨啼日暮江岸边，绿芜连山水连天。","来时十三今十五，一成新衣已再补。","鸿雁南飞报邻伍，在家欢乐辞家苦。","天晴露白钟漏迟，泪痕满面看竹枝。","曲终寒竹风袅袅，西方落日东方晓。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["儿童"],"植物":["竹子"]},"theme_conf":0.586},{"uid":"a87be94b-e983-40ff-8350-48a16dbfc585","title":"过严君平古井","author":"郑世翼","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严平本高尚，远蹈古人风。","卖卜成都市，流名大汉中。","旧井改人世，寒泉久不通。","多年既罢汲，无禽乃遂空。","如何属秋气，唯见落双桐。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"1b9b8047-2410-47ae-a24c-aad7342b338f","title":"石鼓歌","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["张生手持石鼓文，劝我试作石鼓歌。","少陵无人谪仙死，才薄将奈石鼓何。","周纲陵迟四海沸，宣王愤起挥天戈。","大开明堂受朝贺，诸侯劒佩鸣相磨。","搜于岐阳骋雄俊，万里禽兽皆遮罗。","镌功勒成告万世，凿石作鼓隳嵯峨。","从臣才艺咸第一，拣选撰刻留山阿。","雨淋日炙野火燎，鬼物守护烦㧑呵。","公从何处得纸本，毫发尽备无差讹。","辞严义密读难晓，字体不类隶与科。","年深岂免有缺画，快劒斫断生蛟鼍。","鸾翔凤翥众僊下，珊瑚碧树交枝柯。","金绳铁索锁纽壮，古鼎跃水龙腾梭。","陋儒编诗不收入，二雅褊迫无委蛇。","孔子西行不到秦，掎摭星宿遗羲娥。","嗟予好古生苦晚，对此涕泪双滂沱。","忆昔初蒙博士徴，其年始改称元和。","故人从军在右辅，为我度量掘臼科。","濯冠沐浴告祭酒，如此至宝存岂多。","氊包席裹可立致，十鼓祗载数骆驼。","荐诸太庙比郜鼎，光价岂止百倍过。","圣恩若许留太学，诸生讲解得切磋。","观经鸿都尚填咽，坐见举国来奔波。","剜苔剔藓露节角，安置妥帖平不颇。","大厦深簷与盖覆，经历久远期无佗。","中朝大官老于事，讵肯感激徒媕婀。","牧童敲火牛砺角，谁复著手为摩挲。","日销月铄就埋没，六年西顾空吟哦。","羲之俗书趁姿媚，数纸尚可博白鹅。","继周八代争战罢，无人收拾理则那。","方今太平日无事，柄任儒术崇丘轲。","安能以此上论列，愿借辨口如悬河。","石鼓之歌止于此，呜呼吾意其蹉跎。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.562},{"uid":"49a7fdb4-f899-42a1-a13f-8397020dc267","title":"相和歌辞 估客乐","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["估客无住著，有利身即行。","出门求火伴，入户辞父兄。","父兄相教示，求利莫求名。","求名有所避，求利无不营。","火伴相勒缚，卖假莫卖诚。","交关少交假，交假本生轻。","自兹相将去，誓死意不更。","一解市头语，便无乡里情。","𨱎石打臂钏，糯米炊项璎。","归来村中卖，敲作金玉声。","村中田舍娘，贵贱不敢争。","所费百钱本，已得十倍赢。","颜色转光净，饮食亦甘馨。","子本频蕃息，货赂日兼幷。","求珠驾沧海，采玉上荆衡。","北买党项马，西擒吐蕃鹦。","炎洲布火浣，蜀地锦织成。","越婢脂肉滑，奚僮眉眼明。","通算衣食费，不计远近程。","经营天下徧，却到长安城。","城中东西市，闻客次第迎。","迎客兼说客，多财为势倾。","客心本明黠，闻语心已惊。","先问十常侍，次求百公卿。","侯家与主第，点缀无不精。","归来始安坐，富与王家勍。","市卒酒肉臭，县胥家舍成。","岂惟绝言语，奔走极使令。","大儿贩材木，巧识梁栋形。","小儿贩盐卤，不入州县征。","一身偃市利，突若截海鲸。","钩距不敢下，下则牙齿横。","生为估客乐，判尔乐一生。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"554a25ee-27ba-40ed-a77c-0edde1d4fea2","title":"戏作花卿歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["成都猛将有花卿，学语小儿知姓名。","用如快鹘风火生，见贼唯多身始轻。","緜州副使著柘黄，我卿埽除即日平。","子章髑髅血糢糊，手提掷还崔大夫。","李侯重有此节度，人道我卿绝世无。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花"],"cats":{"人物":["儿童"]},"theme_conf":0.72},{"uid":"d453f469-2a2c-48a1-8581-0193560729f3","title":"进艇","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南京久客耕南亩，北望伤神坐北窗。","昼引老妻乘小艇，晴看稚子浴清江。","俱飞蛱蝶元相逐，并蔕芙蓉本自双。","茗饮蔗浆携所有，瓷甖无谢玉为缸。"],"theme":"亲情","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"人物":["儿童"]},"theme_conf":1.0},{"uid":"dc7dd19a-d828-4de2-98fe-74df8749af86","title":"漫酬贾沔州","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往年壮心在，尝欲济时难。","奉诏举州兵，令得诛暴叛。","上将屡颠覆，偏师尝救乱。","未曾弛戈甲，终日领簿案。","出入四五年，忧劳忘昏旦。","无谋静凶丑，自觉愚且愞。","岂欲皂枥中，争食麧与藖。","去年辞职事，所惧贻忧患。","天子许安亲，官又得闲散。","自家樊水上，性情尤荒慢。","云山与水木，似不憎吾漫。","以兹忘时世，日益无畏惮。","漫醉人不嗔，漫眠人不唤。","漫游无远近，漫乐无早晏。","漫中漫亦忘，名利谁能算。","闻君劝我意，为君一长叹。","人谁年八十，我已过其半。","家中孤弱子，长子未及冠。","且为儿童主，种药老谿涧。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["儿童"]},"theme_conf":0.96},{"uid":"cp6c060097980e4f","title":"虞美人","author":"叶梦得","dynasty":"宋","section":"宋词","form":"词","paragraphs":["落花已作风前舞。","又送黄昏雨。","晓来庭院半残红。","惟有游丝千丈、晴空。","殷勤花下同携手。","更尽杯中酒。","美人不用敛蛾眉。","我亦多情、无奈酒阑时。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","园林","夜","花"],"cats":{"抒情":["伤感"],"人物":["女子"]},"theme_conf":1.0},{"uid":"0a0f9231-d88c-4f81-b941-83b67a736194","title":"长恨歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["夜","楼","山","春","秋","园林"],"cats":{"抒情":["爱情","伤感","孤独","闺怨","感恩"],"四季":["春天","秋天"],"天气":["写雨","星星"],"人物":["老师"],"人生":["梦想"]},"theme_conf":0.85},{"uid":"5a5a657c-624e-44c1-8abd-4318953d1c56","title":"送臯法师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江草知寒柳半衰，行吟怨别独迟迟。","何人讲席投如意，唯有东林远法师。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["庐山"],"人物":["老师"]},"theme_conf":1.0},{"uid":"e2f6d3a1-da3e-4651-a066-b9cb1c339757","title":"赋得亚父碎玉斗","author":"裴次元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雄谋竟不决，宝玉将何爱。","倏尔霜刃挥，飒然春冰碎。","飞光动旗帜，散响惊环珮。","霜浓绣帐前，星流锦筵内。","图王业已失，为虏言空悔。","独有青史中，英风冠千载。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春","秋","冬"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人物":["父亲"]},"theme_conf":0.524},{"uid":"6045a96b-444d-4bc2-adb7-84baa1d21591","title":"杜秀才画立走水牛歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昆仑儿，骑白象，时时锁著师子项。","奚奴跨马不搭鞍，立走水牛惊汉官。","江村小儿好夸骋，脚踏牛头上牛领。","浅草平田攃过时，大虫著钝几落井。","杜生知我恋沧州，画作一障张床头。","八十老婆拍手笑，妬他织女嫁牵牛。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.634},{"uid":"3a07b10d-d744-4217-9ed1-39199b7ec44f","title":"送王六觐巢县叔父二首 二","author":"李涉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长忆山阴旧会时，王家兄弟尽相随。","老来放逐潇湘路，泪滴秋风引献之。"],"theme":"送别","theme2":["亲情"],"style":"沉郁","style2":["旷达","婉约"],"mood":"愁怨","mood2":["相思"],"scene":["秋","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.603},{"uid":"41e3f463-1460-4aed-a203-56402ea427ef","title":"戏招诸客","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄醅绿醑迎冬熟，绛帐红炉逐夜开。","谁道洛中多逸客，不将书唤不曾来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"人物":["老师"]},"theme_conf":1.0},{"uid":"b96a1832-961d-48f5-9004-7ea944e8c071","title":"代琵琶弟子谢女师曹供奉寄新调弄谱","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["琵琶师在九重城，忽得书来喜且惊。","一纸展看非旧谱，四弦翻出是新声。","蕤宾掩抑娇多怨，散水玲珑峭更清。","珠颗泪沾金捍拨，红妆弟子不胜情。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["清新","幽峭"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","感恩"],"人物":["老师"]},"theme_conf":0.769},{"uid":"ab09e37b-0114-49f7-ab82-56480afb3d9e","title":"游子行","author":"聂夷中","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["萱草生堂阶，游子行天涯。","慈亲倚门望，不见萱草花。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["母亲"]},"theme_conf":0.68},{"uid":"f5436455-4bdd-4425-96c5-12ed92905950","title":"重幸武功","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["代马依朔吹，惊禽愁昔丛。","况兹承眷德，怀旧感深衷。","积善忻余庆，畅武悦成功。","垂衣天下治，端拱车书同。","白水巡前迹，丹陵幸旧宫。","列筵欢故老，高宴聚新丰。","驻跸抚田畯，回舆访牧童。","瑞气萦丹阙，祥烟散碧空。","孤屿含霜白，遥山带日红。","于焉欢击筑，聊以咏南风。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"人物":["儿童"]},"theme_conf":0.65},{"uid":"6d843e05-dc54-4fd9-beb9-44f188b596b3","title":"奉和王侍郎春日喜李侍郎崔给谏张舍人韦谏议见访因命觞观乐之什","author":"窦庠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["华馆迟嘉宾，逢迎淑景新。","锦筵开绛帐，玉佩下朱轮。","曲里三仙会，风前百啭春。","欲知忘味处，共仰在齐人。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春","酒"],"cats":{"四季":["春天"],"人物":["老师"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"1f1220b8-28ca-4ded-b86b-11a6f4a7c0e7","title":"红叶","author":"罗隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不奈荒城畔，那堪晚照中。","野晴霜浥绿，山冷雨催红。","游子灞陵道，美人长信宫。","等闲居岁暮，摇落意无穷。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["花","雨","山"],"cats":{"人物":["女子"],"植物":["叶子"]},"theme_conf":0.86},{"uid":"0336e989-ea54-4fdc-80b6-ffd5c6595a35","title":"热三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雷霆空霹雳，云雨竟虚无。","炎赫衣流汗，低垂气不苏。","乞为寒水玉，愿作冷秋菰。","何似儿童岁，风凉出舞雩。"],"theme":"咏怀抒感","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","雨","夏"],"cats":{"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.83},{"uid":"6d47c928-e6dd-4417-a9a5-acb7d4272e84","title":"新乐府 陵园妾\t怜幽闭也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["陵园妾，颜色如花命如叶。","命如叶薄将奈何，一奉寝宫年月多。","年月多，时光换，春愁秋思知何限。","青丝发落丛鬓疎，红玉肤销系帬慢。","忆昔宫中被妬猜，因谗得罪配陵来。","老母啼呼趁车别，中官监送鏁门回。","山宫一闭无开日，未死此身不令出。","松门到晓月裴回，柏城尽日风萧瑟。","松门柏城幽闭深，闻蝉听燕感光阴。","眼看菊蘂重阳泪，手把棃花寒食心。","把花掩泪无人见，绿芜墙绕青苔院。","四季徒支妆粉钱，三朝不识君王面。","遥想六宫奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，犹闻不啻三千人。","三千人，我尔君恩何厚薄。","愿令轮转直陵园，三岁一来均苦乐。"],"theme":"闺情宫怨","theme2":["送别","节令风俗"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["园林","重阳"],"cats":{"抒情":["伤感","闺怨"],"人物":["母亲"],"人生":["时光"],"节日":["寒食节","重阳节"]},"theme_conf":0.266},{"uid":"cb55e33f-ee4d-4b88-a23f-280fd0cfd271","title":"杂曲歌辞 春日行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["深宫高楼入紫清，金作蛟龙盘绣楹。","佳人当窗弄白日，弦将手语弹鸣筝。","春风吹落君王耳，此曲乃是升天行。","因出天池泛蓬瀛，楼船蹙沓波浪惊。","三千双蛾献歌笑，挝钟考鼓宫殿倾。","万姓聚舞歌太平，我无为，人自宁。","三十六帝欲相迎，仙人飘翩下云𫐌。","帝不去，留镐京。","安能为轩辕，独往入窅冥。","小臣拜献南山寿，陛下万古垂鸿名。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["太阳"],"人物":["女子"]},"theme_conf":0.65},{"uid":"96afd27a-b059-4d11-9430-d3bf951080a3","title":"题商山店","author":"韩琮","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["商山驿路几经过，未到仙娥见谢娥。","红锦机头抛皓腕，绿云鬟下送横波。","佯嗔阿母留宾客，暗为王孙换绮罗。","碧涧门前一条水，岂知平地有天河。"],"theme":"爱情相思","theme2":["羁旅思乡","咏物"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"人物":["母亲"]},"theme_conf":0.8},{"uid":"09e503f0-2aaf-4625-a805-f3960d19d9cd","title":"渔父歌沧浪赋附歌 二","author":"何蠲","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["泛蓬𦩘戏凫鹥，澄水暗（一作「镜」）兮照虹霓。","指尘路兮何足迷，来濯缨兮沧浪溪。","（见伯二四八八、二六二一、二七一二卷，兹从张锡厚校录本。","）。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"天气":["彩虹"],"人物":["父亲"]},"theme_conf":0.714},{"uid":"bdb3235d-6261-4b85-b5f5-53fc016942c3","title":"渔父歌 五","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青草湖中月正圆，巴陵渔父櫂歌连。","钓车子，橛头船，乐在风波不用仙。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["月","舟"],"cats":{"人物":["父亲"]},"theme_conf":0.613},{"uid":"fa9bde41-de31-4a73-8589-c923ae74ed10","title":"酬令狐舍人","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["晓禁苍苍换直还，暂低鸾翼向人间。","亦知受业公门事，数仞丘墙不见山。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"人物":["老师"]},"theme_conf":0.95},{"uid":"1f0f728d-0c02-4fd4-9976-ba6f0cba1c12","title":"相和歌辞 采莲归","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲归，绿水芙蓉衣，秋风起浪凫雁飞。","桂棹兰桡下长浦，罗裙玉腕摇轻橹。","叶屿花潭极望平，江讴越吹相思苦。","相思苦，佳期不可驻。","塞外征夫犹未还，江南采莲今已暮。","今已暮，摘莲花，今渠那必尽倡家。","官道城南把桑叶，何如江上采莲花？","莲花复莲花，花叶何重叠。","叶翠本羞眉，花红彊如颊。","佳人不兹期，怅望别离时。","牵花怜共蒂，折藕爱连丝。","故情何处所？新物徒华滋。","不惜南津交佩解，还羞北海雁书迟。","采莲歌有节，采莲夜未歇。","正逢浩荡江上风，又值徘徊江上月。","莲浦夜相逢，吴姬越女何丰茸。","共问寒江千里外，征客关山更几重。"],"theme":"爱情相思","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","舟"],"cats":{"抒情":["爱情","离别","思念","思乡"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.374},{"uid":"b04b21d5-0f49-468d-963b-cfc58ae76654","title":"锦树行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["今日苦短昨日休，岁云暮矣增离忧。","霜凋碧树待锦树，万壑东逝无停留。","荒戍之城石色古，东郭老人住青丘。","飞书白帝营斗粟，琴瑟几杖柴门幽。","青草萋萋尽枯死，天马跂足随牦牛。","自古圣贤多薄命，奸雄恶少皆封侯。","故国三年一消息，终南渭水寒悠悠。","五陵豪贵反颠倒，乡里小儿狐白裘。","生男堕地要膂力，一生富贵倾邦国。","莫愁父母少黄金，天下风尘儿亦得。"],"theme":"讽喻刺世","theme2":["羁旅思乡","咏史怀古","边塞征战"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感","怀古"],"人物":["儿童"]},"theme_conf":0.87},{"uid":"f4b72624-5f7c-4885-940b-5c1812023ead","title":"初入秦川路逢寒食","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳芳树映天津，灞岸垂杨窣地新。","直为经过行处乐，不知虚度两京春。","去年余闰今春早，曙色和风著花草。","可怜寒食与清明，光辉幷在长安道。","自从关路入秦川，争道何人不戏鞭。","公子途中妨蹴踘，佳人马上废秋千。","渭水长桥今欲渡，葱葱渐见新丰树。","远看骊岫入云霄，预想汤池起烟雾。","烟雾氛氲水殿开，暂拂香轮归去来。","今岁清明行已晚，明年寒食更相陪。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"人物":["女子"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"d949bec5-34ee-44c3-a70c-ecfa7cb36b0c","title":"玉真张观主下小女冠阿容","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绰约小天仙，生来十六年。","姑山半峰雪，瑶水一枝莲。","晚院花留立，春窗月伴眠。","回眸虽欲语，阿母在傍边。"],"theme":"爱情相思","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","雪","春","月"],"cats":{"四季":["春天"],"人物":["母亲"]},"theme_conf":0.6},{"uid":"a5546090-d778-47ce-abde-d3184e225f64","title":"江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清江一曲抱村流，长夏江村事事幽。","自去自来堂上燕，相亲相近水中鸥。","老妻画纸为碁局，稚子敲针作钓钩。","多病所须唯药物，微躯此外更何求。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"山水":["江河"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.832},{"uid":"b9629e5e-c8bc-47e6-ae9f-2eba96a7fbda","title":"鼓吹曲辞 有所思","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["当时我醉美人家，美人颜色娇如花。","今日美人弃我去，青楼珠箔天之涯。","天涯娟娟常娥月，三五二八盈又缺。","翠眉蝉鬓生别离，一望不见心断绝。","心断绝，几千里，梦中醉卧巫山云。","觉来泪滴湘江水，湘江两岸花木深。","美人不见愁人心，含愁更奏绿绮琴，调高弦绝无知音。","美人兮美人！不知为暮雨兮为朝云。","相思一夜梅花发，忽到窗前疑是君。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"相思","mood2":[],"scene":["夜","酒","江"],"cats":{"抒情":["爱情","友情","离别","思念","伤感"],"人物":["女子"]},"theme_conf":0.367},{"uid":"70327e7a-b43e-446d-8e1b-7e9960187f27","title":"过王舍人宅","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入门花柳暗，知是近臣居。","大隐心何远，高风物自疎。","翛然静者事，宛得上皇余。","鸡犬偷仙药，儿童授道书。","清吟送客后，微月上城初。","彩笔有新咏，文星垂太虚。","承恩金殿宿，应荐马相如。"],"theme":"应制干谒","theme2":["送别","咏物","羁旅思乡"],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.85},{"uid":"250fab5b-4a5c-47bd-8ef0-d9d82e14b16b","title":"亚父碎玉斗","author":"何儒亮","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["嬴女昔解网，楚王有遗躅。","破关既定秦，碎首闻献玉。","贞姿应刃散，清响因风续。","匪狥切泥功，将明怀璧辱。","莫量汉祖德，空受项君勗。","事去见前心，千秋渭水绿。"],"theme":"亲情","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"e09f4a35-1c1b-41f4-a038-6919770c3d22","title":"效陶潜体诗十六首 十四","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有一燕赵士，言貌甚奇瓌。","日日酒家去，脱衣典数杯。","问君何落拓，云仆生草莱。","地寒命且薄，徒抱王佐才。","岂无济时策，君门乏良媒。","三献寝不报，迟迟空手回。","亦有同门生，先升青云梯。","贵贱交道绝，朱门叩不开。","及归种禾黍，三岁旱为灾。","入山烧黄白，一旦化为灰。","蹉跎五十余，生世苦不谐。","处处去不得，却归酒中来。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["酒"],"cats":{"人物":["老师"]},"theme_conf":0.54},{"uid":"ad9f94e9-3bfc-4ef1-912c-efd6fe4b7567","title":"送前进士蔡京赴学究科","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["耳闻战鼓带经锄，振发声名自里闾。","已是世间能赋客，更攻窻下绝编书。","朱门达者谁能识，绛帐书生尽不如。","幸遇天官旧丞相，知君无翼上空虚。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人物":["老师"]},"theme_conf":0.75},{"uid":"46c91e4d-996f-4f29-824a-a2422b6c7971","title":"泥功山","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝行青泥上，暮在青泥中。","泥泞非一时，版筑劳人功。","不畏道途永，乃将汩没同。","白马为铁骊，小儿成老翁。","哀猿透却坠，死鹿力所穷。","寄语北来人，后来莫悤悤。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"人物":["儿童"]},"theme_conf":0.518},{"uid":"a9286dac-14c5-4239-8c1b-bd90bc91baa2","title":"杂歌谣辞 渔父歌 三","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["霅溪湾里钓渔翁，舴艋为家西复东。","江上雪，浦边风，笑著荷衣不叹穷。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","江"],"cats":{"人物":["父亲"]},"theme_conf":0.784},{"uid":"1d7c2618-c8d8-4ff5-a7b6-88ffb05263fe","title":"雨中寒食","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["令节逢烟雨，园亭但掩关。","佳人宿妆薄，芳树彩绳闲。","归思偏消酒，春寒为近山。","花枝不可见，别恨灞陵间。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["清明","雨"],"cats":{"天气":["写雨"],"人物":["女子"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"eaca9abf-2fae-4634-8f47-89acf32a72a1","title":"杂歌谣辞 渔父歌 三","author":"李珣","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["棹警鸥飞水溅袍，影侵潭面柳垂绦。","终日醉，绝尘劳，曾见钱塘八月涛。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","月","江南","酒"],"cats":{"人物":["父亲"]},"theme_conf":0.655},{"uid":"5a8f448f-d34b-4f01-95ca-4c0111970197","title":"摘樱桃赠元居士时在望仙亭南楼与朱道士同处","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["海上朱樱赠所思，楼居况是望仙时。","蓬莱羽客如相访，不是偷桃一小儿。"],"theme":"寄赠酬答","theme2":["游仙梦幻"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["楼"],"cats":{"人物":["儿童"],"植物":["桃花"]},"theme_conf":0.92},{"uid":"8b73dd1d-d744-4620-965f-163b4b45127d","title":"南中春意","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入仕无知言，游方随世道。","平生愿开济，遇物干怀抱。","已阻青云期，甘同散樗老。","客游南海曲，坐见韶阳蚤。","旧国别佳人，他乡思芳草。","惜无鸿鹄翅，安得凌苍昊。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["女子"],"人生":["梦想"]},"theme_conf":0.618},{"uid":"a93b3a91-73b6-4087-8757-5a8f1c8d4161","title":"山斋读书寄时校书杜叟","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日爱蘅茅下，闲观山海图。","幽人自守朴，穷谷也名愚。","倒岭和溪雨，新泉到户枢。","丛兰齐稚子，蟠木老潜夫。","忆戴差过剡，游仙惯入壶。","濠梁时一访，庄叟亦吾徒。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.441},{"uid":"e26934fb-899d-4d12-aeec-81f11c5e903f","title":"送辰州郑使君","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁人不谴谪，君去独堪伤。","长子家无弟，慈亲老在堂。","惊魂随驿吏，冒暑向炎方。","未到猨啼处，参差已断肠。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"人物":["母亲"]},"theme_conf":0.758},{"uid":"b06bff50-6bb7-41ca-8381-ef41b3916169","title":"石鱼湖上作","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾爱石鱼湖，石鱼在湖里。","鱼背有酒樽，绕鱼是湖水。","儿童坐小舫，载酒胜一桮。","座中令酒舫，空去复满来。","湖岸多欹石，石下流寒泉。","醉中一盥漱，快意无比焉。","金玉吾不须，轩冕吾不爱。","且欲坐湖畔，石鱼长相对。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"幽峭","style2":["绮丽","豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江"],"cats":{"人物":["儿童"]},"theme_conf":0.592},{"uid":"a3c6b2bf-35cf-40dc-bbcf-cfb5efa9f82e","title":"送褚大落第东归","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["离琴弹苦调，美人惨向隅。","顷来荷策干明主，还复扁舟归五湖。","汉家侧席明扬久，岂意遗贤在林薮。","玉堂金马隔青云，墨客儒生皆白首。","昨梦芳洲采白苹，归期且喜故园春。","稚子只思陶令至，文君不厌马卿贫。","剡中风月久相忆，池上旧游应再得。","酒熟宁孤芳杜春，诗成不枉青山色。","念此那能不羡归，长杨谏猎事皆违。","他日东流一乘兴，知君为我扫荆扉。"],"theme":"送别","theme2":["羁旅思乡"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":["欢愉","孤寂"],"scene":["舟","园林","江","春"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["春天"],"人物":["女子","儿童"],"人生":["梦想"]},"theme_conf":0.361},{"uid":"cf5eecaf-79f1-484c-93e2-8e28fb3c0816","title":"观八骏图","author":"刘叉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["穆王八骏走不歇，海外去寻长日月。","五云望断阿母宫，归来落得新白发。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"人物":["母亲"],"动物":["写马"]},"theme_conf":1.0},{"uid":"0b722208-9e02-4dac-9ec5-979859eea818","title":"正月三日归溪上有作简院内诸公","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野外堂依竹，篱边水向城。","蚁浮仍腊味，鸥泛已春声。","药许隣人㔉，书从稚子擎。","白头趋幕府，深觉负平生。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","园林","春"],"cats":{"四季":["春天"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.772},{"uid":"489e9d6a-f619-4103-acde-0ba0bdfca086","title":"相和歌辞 蛾眉怨","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见宜春苑中九华殿，飞阁连连直如发。","白日全含朱鸟窗，流云半入苍龙阙。","宫中彩女夜无事，学凤吹箫弄清越。","珠帘北卷待凉风，绣户南开向明月。","忽闻天子忆蛾眉，宝凤衔花揲两螭。","传声走马开金屋，夹路鸣环上玉墀。","长乐彤庭宴华寝，三千美人曳光锦。","灯前含笑更罗衣，帐里承恩荐瑶枕。","不意君心半路回，求仙别作望仙台。","仓琅禁闼遥相忆，紫翠岩房昼不开。","欲向人间种桃实，先从海底觅蓬莱。","蓬莱可求不可上，孤舟缥缈知何往？","黄金作盘铜作茎，晴天白露掌中擎。","王母嫣然感君意，云车雨斾欲相迎。","飞帘观前空怨慕，少君何事须相误。","一朝埋没茂陵田，贱妾蛾眉不重顾。","宫车晚出向南山，仙卫逶迤去不还。","朝晡泣对麒麟树，树下苍苔日渐斑。","人生百年夜将半，对酒长歌莫长叹。","賸知白日不可思，一死一生何足算。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思","欢愉"],"scene":["夜","月","山","楼"],"cats":{"抒情":["思念","闺怨","感恩"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.59},{"uid":"b693eaa3-5152-47da-bb89-56ac4b2d11cd","title":"杂曲歌辞 古别离二首 二","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老母别爱子，少妻送征郎。","血流既四面，乃亦断二肠。","不愁寒无衣，不怕饥无粮。","惟恐征战不还乡，母化为鬼妻为孀。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["离别","伤感"],"人物":["母亲"],"人生":["战争"]},"theme_conf":0.618},{"uid":"6d303931-f900-4f29-a8b9-caea611a521f","title":"寄韩谏议","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["今我不乐思岳阳，身欲奋飞病在床。","美人娟娟隔秋水，濯足洞庭望八荒。","鸿飞冥冥日月白，青枫叶赤天雨霜。","玉京群帝集北斗，或骑骐𬴊翳凤皇。","芙蓉旌旗烟雾乐，影动倒景摇潇湘。","星宫之君醉琼浆，羽人稀少不在旁。","似闻昨者赤松子，恐是汉代韩张良。","昔随刘氏定长安，帷幄未改神惨伤。","国家成败吾岂敢，色难腥腐餐风香。","周南留滞古所惜，南极老人应寿昌。","美人胡为隔秋水，焉得置之贡玉堂。"],"theme":"游仙梦幻","theme2":["送别","边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["星星"],"人物":["女子"]},"theme_conf":0.385},{"uid":"f2db30a1-f125-44b9-a8d8-287ccb69238a","title":"佳人","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绝代有佳人，幽居在空谷。","自云良家子，零落依草木。","关中昔丧败，兄弟遭杀戮。","官高何足论，不得收骨肉。","世情恶衰歇，万事随转烛。","夫壻轻薄儿，新人已如玉。","合昏尚知时，鸳鸯不独宿。","但见新人笑，那闻旧人哭。","在山泉水清，出山泉水浊。","侍婢卖珠回，牵萝补茅屋。","摘花不插发，采柏动盈匊。","天寒翠袖薄，日暮倚修竹。"],"theme":"闺情宫怨","theme2":["亲情","闺情宫怨","闲适隐逸"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["欢愉","悲怆"],"scene":["山"],"cats":{"抒情":["孤独","闺怨"],"人物":["女子"]},"theme_conf":0.85},{"uid":"333b66bc-2738-4424-aaf9-c8834be7fabe","title":"琴曲歌辞 风入松歌","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西岭松声落日秋，千枝万叶风飕飗。","美人援琴弄成曲，写得松间声断续。","声断续，清我魂，流波坏陵安足论。","美人夜坐月明里，含少商兮照清征。","风何凄兮飘飉，搅寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["夜","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.565},{"uid":"b849afe9-f7db-4f53-b688-fafa65b264f1","title":"南海马大夫见惠著述三通勒成四帙上自邃古达于国朝采其菁华至简如富钦受嘉贶诗以谢之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["红旗阅五兵，绛帐领诸生。","味道轻鼎食，退公犹笔耕。","青箱传学远，金匮纳书成。","一瞬见前事，九流当抗行。","编蒲曾苦思，垂竹媿无名。","今日承芳讯，谁言赠衮荣。"],"theme":"寄赠酬答","theme2":["送别","边塞征战"],"style":"豪放","style2":["旷达","绮丽"],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"抒情":["感恩"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.96},{"uid":"59c7eaa9-3c05-4857-8cff-10376706ccb9","title":"月夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今夜鄜州月，闺中只独看。","遥怜小儿女，未解忆长安。","香雾云鬟湿，清辉玉臂寒。","何时倚虚幌，双照泪痕干。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月"],"cats":{"抒情":["思念","孤独","闺怨"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.705},{"uid":"cfec06fe-678e-45b9-8da3-93ed36cb9f9e","title":"单父逢邓司仓覆仓库因而有赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["邦牧今坐啸，群贤趋纪纲。","四人忽不扰，耕者遥相望。","粲粲府中妙，授词如履霜。","炎炎伏热时，草木无晶光。","匹马度睢水，清风何激扬。","校缗阅帑藏，发廪欣斯箱。","邂逅得相逢，欢言至夕阳。","开襟自公余，载酒登琴堂。","举桮挹山川，寓目穷毫芒。","白鸟向田尽，青蝉归路长。","醉中不惜别，况乃正游梁。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","秋","夏"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.88},{"uid":"e1404531-b21b-4e48-b715-9a9ead6cf56c","title":"寄卢仝","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉川先生洛城里，破屋数间而已矣。","一奴长须不裹头，一婢赤脚老无齿。","辛勤奉养十余人，上有慈亲下妻子。","先生结发憎俗徒，闭门不出动一纪。","至今邻僧乞米送，仆忝县尹能不耻。","俸钱供给公私余，时致薄少助祭祀。","劝参留守谒大尹，言语才及輙掩耳。","水北山人得名声，去年去作幕下士。","水南山人又继往，鞍马仆从塞闾里。","少室山人索价高，两以谏官徴不起。","彼皆刺口论世事，有力未免遭驱使。","先生事业不可量，惟用法律自绳己。","春秋三传束高阁，独抱遗经究终始。","往年弄笔嘲同异，怪辞惊众谤不已。","近来自说寻坦途，犹上虚空跨绿駬。","去年生儿名添丁，意令与国充耘耔。","国家丁口连四海，岂无农夫亲耒耜。","先生抱才终大用，宰相未许终不仕。","假如不在陈力列，立言垂范亦足恃。","苗裔当蒙十世宥，岂谓贻厥无基阯。","故知忠孝生天性，洁身乱伦安足拟。","昨晚长须来下状，隔墙恶少恶难似。","每骑屋山下窥阚，浑舍惊怕走折趾。","凭依婚媾欺官吏，不信令行能禁止。","先生受屈未曾语，忽此来告良有以。","嗟我身为赤县令，操权不用欲何俟。","立召贼曹呼伍伯，尽取鼠辈尸诸市。","先生又遣长须来，如此处置非所喜。","况又时当长养节，都邑未可猛政理。","先生固是余所畏，度量不敢窥涯涘。","放纵是谁之过欤，效尤戮仆愧前史。","买羊沽酒谢不敏，偶逢明月曜桃李。","先生有意许降临，更遣长须致双鲤。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春","塞外","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":0.95},{"uid":"d05f4524-071a-4914-97f3-bed8e9683a48","title":"相和歌辞 大堤曲","author":"张柬之","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南国多佳人，莫若大堤女。","玉床翠羽帐，宝袜莲花炬。","魂处自目成，色授开心许。","迢迢不可见，日暮空愁予。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人物":["女子"]},"theme_conf":0.82},{"uid":"c9ef6401-b33c-4077-89bc-f01fc3279dce","title":"莺莺诗","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["殷红浅碧旧衣裳，取次梳头暗澹妆。","夜合带烟笼晓日，牡丹经雨泣残阳。","低迷隐笑原非笑，散漫清香不似香。","频动横波嗔阿母，等闲教见小儿郎。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":["悲怆","欢愉"],"scene":["春","鸟","花","夜","雨"],"cats":{"四季":["春天"],"人物":["母亲","儿童"],"动物":["写鸟"]},"theme_conf":0.88},{"uid":"52119dc8-6af9-49b7-9905-9da1c39360fd","title":"送赵中丞自司金郎转官参山南令狐仆射幕府","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绿树满褒斜，西南蜀路赊。","驿门临白草，县道入黄花。","相府开油幕，门生逐绛纱。","行看布政后，还从入京华。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"人物":["老师"]},"theme_conf":0.483},{"uid":"5400406f-949f-4793-8c52-8cb59b47ac61","title":"忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稚子书传白菊开，西成相滞未容回。","月明阶下窗纱薄，多少清香透入来。"],"theme":"亲情","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"人物":["儿童"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.528},{"uid":"58ba4d44-398a-4af4-9ae5-764f809b0de1","title":"绝句漫兴九首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["糁径杨花铺白毡，点溪荷叶叠青钱。","笋根稚子无人见，沙上凫雏傍母眠。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人物":["儿童"]},"theme_conf":0.593},{"uid":"186aab50-4ead-4c61-9764-1867aec86f52","title":"寄张十二山人彪三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["独卧蒿阳客，三违颍水春。","艰难随老母，惨澹向时人。","谢氏寻山屐，陶公漉酒巾。","群凶弥宇宙，此物在风尘。","历下辞姜被，关西得孟邻。","早通交契密，晚接道流新。","静者心多妙，先生艺绝伦。","草书何太苦，诗兴不无神。","曹植休前辈，张芝更后身。","数篇吟可老，一字买堪贫。","将恐曾防寇，深潜托所亲。","宁闻倚门夕，尽力洁飧晨。","疎嬾为名误，驱驰丧我真。","索居犹寂寞，相遇益悲辛。","流转依边徼，逢迎念席珍。","时来故旧少，乱后别离频。","世祖修高庙，文公赏从臣。","商山犹入楚，源水不离秦。","存想青龙秘，骑行白鹿驯。","耕岩非谷口，结草即河滨。","肘后符应验，囊中药未陈。","旅怀殊不惬，良觌渺无因。","自古皆悲恨，浮生有屈伸。","此邦今尚武，何处且依仁。","鼓角凌天籁，关山信月轮。","官场罗镇碛，贼火近洮岷。","萧索论兵地，苍茫鬬将辰。","大军多处所，余孽尚纷纶。","高兴知笼鸟，斯文起获麟。","穷秋正摇落，回首望松筠。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","羁旅思乡"],"style":"冲淡","style2":["悲慨","雄浑"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"a1d0535f-ea83-4c32-afc7-6a2e6fd5ed64","title":"舞曲歌辞 白纻辞三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["月寒江清夜沈沈，美人一笑千黄金。","垂罗舞縠扬哀音，郢中白雪且莫吟，子夜吴歌动君心。","动君心，冀君赏。","愿作天池双鸯鸯，一朝飞去青云上。"],"theme":"爱情相思","theme2":[],"style":"旷达","style2":["绮丽"],"mood":"欢愉","mood2":["悲怆"],"scene":["雪","夜","月","江","江南"],"cats":{"人物":["女子"]},"theme_conf":0.68},{"uid":"f69f9c09-d812-4d6a-9650-bbbbcad29caa","title":"清明二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["朝来新火起新烟，湖色春光净客船。","绣羽衔花他自得，红颜骑竹我无缘。","胡童结束还难有，楚女腰肢亦可怜。","不见定王城旧处，长怀贾傅井依然。","虚沾焦举为寒食，实藉严君卖卜钱。","钟鼎山林各天性，浊醪粗饭任吾年。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"人物":["父亲"],"节日":["寒食节","清明节"]},"theme_conf":0.84},{"uid":"f646a1ae-7a3e-4cdb-96d4-8c2ab4fb899a","title":"露青竹杖歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["鲜于仲通正当年，章仇兼琼在蜀川。","约束蜀儿采马鞭，蜀儿采鞭不敢眠。","横截斜飞飞鸟边，绳桥夜上层崖颠。","头插白云跨飞泉，采得马鞭长且坚。","浮沤丁子珠联联，灰煮蜡楷光烂然。","章仇兼琼持上天，上天雨露何其偏。","飞龙闲厩马数千，朝饮吴江夕秣燕。","红尘扑辔汗湿鞯，师子麒麟聊比肩。","江面昆明洗刷牵，四蹄踏浪头枿天。","蛟龙稽颡河伯虔，拓羯胡雏脚手鲜。","陈闳韩干丹青妍，欲貌未貌眼欲穿。","金鞍玉勒锦连干，骑入桃花杨柳烟。","十二楼中奏管弦，楼中美人夺神仙。","争爱大家把此鞭，禄山入关关破年。","忽见扬州北邙前，秪有人还千一钱。","亭亭笔直无皴节，磨捋形相一条铁。","市头格是无人别，江海贱臣不拘絏。","垂窗挂影西窗缺，稚子觅衣挑仰穴。","家童拾薪几拗折，玉润犹沾玉垒雪。","碧鲜似染苌弘血，蜀帝城边子规咽。","相如桥上文君绝，往年策马降至尊。","七盘九折横剑门，穆王八骏超昆仑。","安用冉冉孤生根，圣人不贵难得货，金玉珊珊谁买恩。"],"theme":"讽喻刺世","theme2":["山水田园","游仙梦幻","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["雪","楼","鸟"],"cats":{"抒情":["孤独"],"人物":["女子","儿童"],"生活":["写桥"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"eb5774b6-2822-479b-92ab-c4028ec564bd","title":"送张淑归觐叔父","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日惨长亭暮，天高大泽闲。","风中闻草木，雪里见江山。","马向塞云去，人随古道还。","阮家今夜乐，应在竹林间。"],"theme":"送别","theme2":[],"style":"雄浑","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["塞外","雪","夜","江","山"],"cats":{"抒情":["离别"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"114a62cf-942e-4515-aa95-8988f3a30e72","title":"将归旧山留别孟郊","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["择木无利刃，羡鱼无巧纶。","如何不量力，自取中路贫。","前者不厌耕，一日不离亲。","今来千里外，我心不在身。","悠悠慈母心，惟愿才如人。","蚕桑能几许，衣服常著新。","一饭吐尺丝，谁见此殷勤。","别君归耕去，持火烧车轮。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别","感恩"],"人物":["母亲"]},"theme_conf":0.483},{"uid":"a9d85d1f-936c-489c-a074-9e2be10e5af6","title":"遣闷奉呈严公二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["白水鱼竿客，清秋鹤发翁。","胡为来幕下，秪合在舟中。","黄卷真如律，青袍也自公。","老妻忧坐[痹]，幼女问头风。","平地专欹倒，分曹失异同。","礼甘衰力就，义忝上官通。","畴昔论诗蚤，光辉仗钺雄。","宽容存性拙，剪拂念途穷。","露裛思藤架，烟霏想桂丛。","信然龟触网，直作鸟窥笼。","西岭纡村北，南江遶舍东。","竹皮寒旧翠，椒实雨新红。","浪簸船应坼，杯干瓮即空。","藩篱生野径，斤斧任樵童。","束缚酬知己，蹉跎効小忠。","周防期稍稍，太简遂悤悤。","晓入朱扉启，昏归画角终。","不成寻别业，未敢息微躬。","乌鹊愁银汉，驽骀怕锦幪。","会希全物色，时放倚梧桐。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","舟","雨"],"cats":{"抒情":["友情","伤感"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.374},{"uid":"e4545449-1757-4265-96bb-8fb65870b953","title":"池州夫子庙麟台","author":"韦表微","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["二仪既闭，三象乃乖。","圣道埋郁，人心不开。","上无文武，下有定哀。","吁嗟麟兮，孰为来哉。","周虽不纲，孔实嗣圣。","诗书既删，礼乐大定。","劝善惩恶，奸邪乃正。","吁嗟麟兮，克昭符命。","圣与时合，化行位尊。","苟或乖戾，身穷道存。","于昭鲁邑，栖迟孔门。","吁嗟麟兮，孰知其仁。","运极数残，德至时否。","楚国寖广，秦封益侈。","墙仞迫阨，崎岖阙里。","吁嗟麟兮，靡有攸止。","世治则麟，世乱则麕。","出非其时，麋鹿同群。","孔不自圣，麟不自祥。","吁嗟麟兮，天何所亡。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["园林","楼"],"cats":{"抒情":["怀古"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.9},{"uid":"0d6eed96-a408-4c95-9d9a-fc1ba93675fc","title":"渔父","author":"张志和","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["八月九月芦花飞，南谿老人垂钓归。","秋山入帘翠滴滴，野艇倚槛云依依。","却把渔竿寻小径，闲梳鹤发对斜晖。","翻嫌四皓曾多事，出为储皇定是非。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["月","秋","山"],"cats":{"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.556},{"uid":"3e58f1b4-21c8-4f73-a641-cc0366ab1efd","title":"寄上兵部韩侍郎奉呈李户部卢刑部杜三侍郎","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["道路五千里，门阑三十年。","当时携手人，今日无半全。","咏题官舍内，赋韵僧房前。","公登略彴桥，况榜龙{舟卬}船。","远寺吐朱阁，春潮浮绿烟。","鹓鸿翔邓林，沙鸨飞吴田。","诸子纷出祖，中宵久留连。","坐客三千人，皆称主人贤。","国士分如此，家臣亦依然。","身在薜萝中，头刺文案边。","故吏已重叠，门生从联翩。","得罪为何名，无阶问皇天。","出门多岐路，命驾无由缘。","伏承诸侍郎，顾念犹迍邅。","圣代逢三宥，营魂空九迁。"],"theme":"应制干谒","theme2":["应制干谒","哲理悟道"],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"人物":["老师"],"人生":["战争"],"生活":["写桥"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"9973b5a9-2259-428d-8d11-9bf2368a32e9","title":"和杨郎中贺杨仆射致仕后杨侍郎门生合宴席上作","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["业重关西继大名，恩深阙下遂高情。","祥鳣降伴趋庭鲤，贺燕飞和出谷莺。","范蠡舟中无子弟，疏家席上欠门生。","可怜玉树连桃李，从古无如此会荣。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟","春","舟","园林"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.89},{"uid":"c3831d44-dbc6-4ad8-87e2-d39388ddc2f2","title":"步虚","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母亲教学步虚，三元长遣下蓬壶。","云韶韵俗停瑶瑟，鸾鹤飞低拂宝炉。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":0.65},{"uid":"5052c292-7fcd-4d89-90f8-f585cba128be","title":"却渡西陵别越中父老","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["海潮晚上江风急，津吏篙师语默齐。","倾手奉觞看故老，拥流争拜见孩提。","慙非杜母临襄岘，自鄙朱翁别会稽。","渐举云帆烟水阔，杳然凫雁各东西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江","江南","酒","舟"],"cats":{"抒情":["离别"],"人物":["父亲"]},"theme_conf":0.522},{"uid":"021b47d2-ef8a-42ca-a7c6-8a8bbb39a98a","title":"简简吟","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["苏家小女名简简，芙蓉花顋柳叶眼。","十一把镜学点妆，十二抽针能绣裳。","十三行坐事调品，不肯迷头白地藏。","玲珑云髻生花样，飘飖风袖蔷薇香。","殊姿异态不可状，忽忽转动如有光。","二月繁霜杀桃李，明年欲嫁今年死。","丈人阿母勿悲啼，此女不是凡夫妻。","恐是天仙谪人世，只合人间十三岁。","大都好物不坚牢，彩云易散琉璃脆。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["伤感","闺怨"],"天气":["写云"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"4e409fd6-6f44-40e3-82b0-3c0fb1f146ef","title":"秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄","author":"鲍防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["前月月明夜，美人同远光。","清尘一以间，今夕坐相忘。","风落芙蓉露，疑余绣被香。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"冲淡","style2":["沉郁","清新"],"mood":"相思","mood2":["欢愉"],"scene":["中秋","月","夜","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"天气":["月亮"],"人物":["女子"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"cpf852a8c541e368","title":"菩萨蛮","author":"李师中","dynasty":"宋","section":"宋词","form":"词","paragraphs":["子规啼破城楼月。","画船晓载笙歌发。","两岸荔枝红。","万家烟雨中。","佳人相对泣。","泪下罗衣湿。","从此信音稀。","岭南无雁飞。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","月","舟","雨","鸟"],"cats":{"抒情":["思乡","伤感"],"人物":["女子"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"cp7755e2bdab1251","title":"解佩环・疏影","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江空不渡，恨蘼芜杜若，零落无数。","远道荒寒，婉娩流年，望望美人迟暮。","风烟雨雪阴晴晚，更何须，春风千树。","尽孤城、落木萧萧，日夜江声流去。","日晏山深闻笛，恐他年流落，与子同赋。","事阔心违，交淡媒劳，蔓草沾衣多露。","汀洲窈窕馀醒寐，遗浮沈沣浦。","有白鸥淡月，微波寄语，逍遥容与。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜"],"cats":{"抒情":["孤独"],"人物":["女子"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.5},{"uid":"9de495a6-9a74-4dc7-b14e-8577611ba318","title":"送王六觐巢县叔父二首 一","author":"李涉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["巢岸南分战鸟山，水云程尽到东关。","弦歌自是君家事，莫怪今来一邑闲。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人物":["父亲"]},"theme_conf":0.438},{"uid":"f7834822-cd95-4e21-b8b3-62cedc27237d","title":"漫歌八曲 将牛何处去二首 一","author":"元结","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["将牛何处去，耕彼故城东。","相伴有田父，相欢惟牧童。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人物":["儿童"]},"theme_conf":0.65},{"uid":"14b59e7e-8085-40bd-89eb-9c83003ce625","title":"陪郑广文游何将军山林十首 九","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["床上书连屋，阶前树拂云。","将军不好武，稚子总能文。","醒酒微风入，听诗静夜分。","𫄨衣挂萝薜，凉月白纷纷。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["山","酒","夜","月"],"cats":{"人物":["儿童"]},"theme_conf":0.635},{"uid":"ef9b9e25-0e0d-4eca-83c6-43d1b4fa241f","title":"赠渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芦花深泽静垂纶，月夕烟朝几十春。","自说孤舟寒水畔，不曾逢著独醒人。"],"theme":"闲适隐逸","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春","舟","月"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"664ccc00-6def-413f-94ac-733c4ec9b6c1","title":"杂曲歌辞 君子有所思行 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我爱正考甫，思贤作商颂。","我爱扬子云，理乱皆如凤。","振衣中夜起，露花香旖旎。","扑碎骊龙明月珠，敲出凤凰五色髓。","陋卷萧萧风淅淅，缅想斯人胜珪璧。","寂寥千载不相逢，无限区区尽虚掷。","君不见沈约道，佳人不在兹，春光为谁惜。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["月","花"],"cats":{"抒情":["思念","怀古"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.86},{"uid":"2b7e4088-5605-41dc-8565-bcce73c7dfad","title":"相和歌辞 楚妃怨","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["梧桐叶下黄金井，横架辘轳牵素绠。","美人初起天未明，手拂银缾秋水冷。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"3cc093e1-e345-4ffe-9721-f49b48891cfa","title":"洛下送牛相公出镇淮南","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北阙至东京，风光十六程。","坐移丞相阁，春入广陵城。","红斾拥双节，白须无一茎。","万人开路看，百吏立班迎。","阃外君弥重，尊前我亦荣。","何须身自得，将相是门生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","楼"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.689},{"uid":"85a83aa1-746f-4baa-bc0f-deaf8de5fdcd","title":"相和歌辞 白头吟","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳城东桃李花，飞来飞去落谁家。","洛阳女儿惜颜色，行逢落花长叹息。","今年花落颜色改，明年花开复谁在。","已见松柏摧为薪，更闻桑田变成海。","古人无复洛城东，今人还对落花风。","年年岁岁花相似，岁岁年年人不同。","寄言全盛红颜子，须怜半死白头翁。","此翁白头真可怜，伊昔红颜美少年。","公子王孙芳树下，清歌妙舞落花前。","光禄池台文锦绣，将军楼阁画神仙。","一朝卧病无人识，三春行乐在谁边。","宛转蛾眉能几时，须臾白发乱如丝。","但看旧来歌舞地，惟有黄昏鸟雀悲。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","花","春","夜"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.477},{"uid":"0c7f80dd-29e4-4c72-b4b5-f967aa52b51a","title":"渔父歌 一","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西塞山前白鹭飞，桃花流水鳜鱼肥。","青篛笠，绿蓑衣，斜风细雨不须归。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","塞外"],"cats":{"天气":["写雨"],"人物":["父亲"]},"theme_conf":0.642},{"uid":"b71efa80-e3d4-490a-baf6-89375f9f1bd8","title":"赠凌仙姥","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母从天降几时，前朝惟有汉皇知。","仙桃不啻三回熟，饱见东方一小儿。"],"theme":"寄赠酬答","theme2":["游仙梦幻"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人物":["母亲","儿童"]},"theme_conf":0.8},{"uid":"8a851893-3a56-4c0c-8252-ab34c95847ed","title":"德宗皇帝挽歌词四首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["执象宗玄祖，贻谋启孝孙。","文高柏梁殿，礼薄霸陵原。","宫仗辞天阙，朝仪出国门。","生成不可报，二十七年恩。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["悼亡"],"人物":["老师"]},"theme_conf":0.99},{"uid":"249ae962-2611-4d4f-aeca-7252cc60fafa","title":"夫子鼓琴得其人","author":"白行简","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["宣父穷玄奥，师襄授素琴。","稍殊流水引，全辨圣人心。","慕德声逾感，怀人意自深。","泠泠传妙手，摵摵振空林。","促调清风至，操弦白日沈。","曲终情不尽，千古仰知音。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["友情","思念"],"人物":["老师"]},"theme_conf":0.86},{"uid":"f8bbfe74-0389-473a-a93d-abe9690a4761","title":"杂歌谣辞 渔父歌","author":"欧阳炯","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["风浩寒溪照胆明，小君山上玉蟾生。","荷露坠，翠烟轻，拨[拉]游鱼几处惊。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["山","月"],"cats":{"人物":["父亲"]},"theme_conf":0.717},{"uid":"0da128ae-3425-4b49-9dd3-1c1cd99e9030","title":"读史","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鬼书报秦亡，天地亦云闭。","赤龙吟大野，老[母]哭白帝。","苍苍无白日，项氏徒先济。","六合已姓刘，鸿门事难制。","坑降嬴政在，衣锦人望替。","宿昔见汉兵，龙蛇满旌棨。","始矜山可拔，终叹骓不逝。","区区亚父心，未究天人际。","萧张马无汗，盛业垂千世。"],"theme":"咏史怀古","theme2":["亲情"],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"f8be67bb-49b2-45d0-b4ce-f6ff1996ad74","title":"送徐五纶南行过吴","author":"顾非熊","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴门东去路三千，到得阊门暂泊船。","老父出迎应倒屣，贫居江上信谁传。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南"],"cats":{"人物":["父亲"]},"theme_conf":0.695},{"uid":"5b4779dc-84b7-41d9-80b9-f7fd0393594f","title":"送刘道士之成都严真观","author":"项斯","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["严君名不朽，道出二经中。","归去精诚恳，还应梦寐通。","池台镜定月，松桧雨余风。","想对灵玄忆，人间恋若空。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","雨"],"cats":{"抒情":["思念"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"ee1af307-1e4b-4b18-a2d9-1194784cae0a","title":"寄张仲甫","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["悲风生旧浦，云岭隔东田。","伏腊同鸡黍，柴门闭雪天。","孤村明夜火，稚子候归船。","静者心相忆，离居畏度年。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","夜","舟"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.94},{"uid":"517b0595-b7cd-41dc-9ee7-b8b4a9a2f076","title":"辞辇行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家代久淳风薄，帝重微行极荒乐。","青娥三千奉一人，班女不以色事君。","朝停玉辇诏同载，三十六宫皆眄睐。","不惊六马缓天仪，从容鸣环前致辞。","君恩如海深难竭，妾命如丝轻易绝。","愿陪阿[母]同小星，敢使太阳齐万物。","周末幽王不可宗，妾闻上圣遗休风。","五更三老待白日，八十一女居深宫。","愿将辇内有余席，回赐忠臣妾恩泽。"],"theme":"闺情宫怨","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","闺怨"],"人物":["母亲"]},"theme_conf":0.609},{"uid":"8cfe8a30-6a98-494e-914b-243ecdf09b25","title":"步虚词二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母种桃云海际，花落子成三千岁。","海风吹折最繁枝，跪捧琼盘献天帝。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":1.0},{"uid":"aaf62ace-7464-47ef-a354-f952b9e2d2a9","title":"终南秋雪","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南岭见秋雪，千门生早寒。","闲时驻马望，高处卷帘看。","雾散琼枝出，日斜铅粉残。","偏宜曲江上，倒影入清澜。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","秋"],"cats":{"四季":["秋天"],"天气":["写雪"],"人物":["老师"]},"theme_conf":0.92},{"uid":"e2fec465-cea1-4829-b12d-3ba37a267562","title":"同从弟销南斋玩月忆山阴崔少府","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高卧南斋时，开帷月初吐。","清辉淡水木，演漾在窗户。","苒苒几盈虚，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹兰杜。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.503},{"uid":"aae1a96c-39e5-4b58-be2e-232eff1e671f","title":"惜花三首 二","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["老鸦拍翼盘空疾，准拟浮生如瞬息。","阿母蟠桃香未齐，汉皇骨葬秋山碧。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花","秋"],"cats":{"四季":["秋天"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"e70730a9-552c-481c-aadc-364713afd410","title":"横吹曲辞 折杨柳","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂杨拂绿水，摇艳东风年。","花明玉关雪，叶暖金窗烟。","美人结长恨，相对心凄然。","攀条折春色，远寄龙庭前。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"植物":["柳树"]},"theme_conf":0.526},{"uid":"db9d91d8-9d41-4922-82a7-1c8d23f66238","title":"秋夜梁七兵曹同宿二首 二","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["好欲弃吾道，今宵又遇君。","老夫相劝酒，稚子待题文。","月下谁家笛，城头几片云。","如何此幽兴，明日重离群。"],"theme":"寄赠酬答","theme2":["亲情","边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"09366fe4-04f9-4665-abc0-810b9a9c6720","title":"投简成华两县诸子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赤县官曹拥材杰，软裘快马当冰雪。","长安苦寒谁独悲，杜陵野老骨欲折。","南山豆苗早荒秽，青门瓜地新冻裂。","乡里儿童项领成，朝廷故旧礼数绝。","自然弃掷与时异，况乃疎顽临事拙。","饥卧动即向一旬，敝裘何啻联百结。","君不见空墙日色晚，此老无声泪垂血。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["冬","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人物":["儿童"]},"theme_conf":0.73},{"uid":"3e457b1c-8c36-46fe-bca9-14cf644ec9ca","title":"相和歌辞 蒿里","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兔不迟，乌更急，但恐穆王八骏，著鞭不及。","所以蒿里，坟出蕺蕺，气凌云天，龙腾凤集，尽为风消土吃，狐掇蚁拾。","黄金不啼玉不泣，白杨骚屑。","乱风愁月，折碑石人。","莽秽榛没，牛羊窸窣。","时见牧童儿，弄枯骨。"],"theme":"悼亡挽歌","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":["悲怆"],"scene":["月"],"cats":{"抒情":["伤感","悼亡"],"人物":["儿童"]},"theme_conf":0.98},{"uid":"027bd68f-e4fa-4564-a2cd-f18352352932","title":"梨园弟子","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["白头垂泪话梨园，五十年前雨露恩。","莫问华清今日事，满山红叶鏁宫门。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感","闺怨","怀古"],"人物":["老师"],"植物":["梨花"]},"theme_conf":0.624},{"uid":"b79db72a-d0ca-42d1-846e-43cb64cea188","title":"杂曲歌辞 行路难五首 四","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见道傍树有寄生枝，青青郁郁同荣衰。","无情之物尚如此，为人不及还堪悲。","父归坟兮未朝夕，已分黄金争田宅。","高堂老母头似霜，心作数支泪常滴。","我闻忽如负芒刺，不独为君空叹息。","古人尺布犹可缝，浔阳义犬令人忆。","寄言世上为人子，孝义团圆莫如此。"],"theme":"亲情","theme2":["送别","悼亡挽歌"],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":[],"cats":{"抒情":["思念","伤感","孤独","悼亡"],"人物":["母亲"]},"theme_conf":0.8},{"uid":"ee380cd0-fea2-4baa-92b7-c82c834265e6","title":"相和歌辞  豫章行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["胡风吹代马，北拥鲁阳关。","吴兵照海雪，西讨何时还？","半渡上辽津，黄云惨无颜。","老母与子别，呼天野草间。","白马绕旌旗，悲鸣相追攀。","白杨秋月苦，早落豫章山。","本为休明人，斩虏素不闲。","岂惜战鬬死，为君埽凶顽。","精感石没羽，岂忘惮险艰。","楼船若鲸飞，波荡落星湾。","此曲不可奏，三军鬓成斑。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","秋","月","楼","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["母亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.582},{"uid":"7782bee4-6ffc-4909-b441-71ab6cd74692","title":"南泾渔父","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["予方任疎慵，地僻即所好。","江流背村落，偶往心已嫪。","田家相去远，岑寂且纵傲。","出户手先筇，见人头未帽。","南泾有渔父，往往携稚造。","问其所以渔，对我真蹈道。","我初簎鱼鼈，童丱至于耄。","窟穴与生成，自然通壶奥。","孜孜戒吾属，天物不可暴。","大小参去留，候其孳养报。","终朝获鱼利，鱼亦未常耗。","同覆天地中，违仁辜覆焘。","余观为政者，此意谅难到。","民皆死搜求，莫肯兴愍悼。","今年川泽旱，前岁山源潦。","牒诉已盈庭，闻之类禽噪。","譬如死鸡鹜，岂不容乳抱。","孟子讥宋人，非其揠苗躁。","吾嘉渔父旨，雅叶贤哲操。","倘遇采诗官，斯文诚敢告。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["旷达"],"mood":"孤寂","mood2":["悲怆"],"scene":[],"cats":{"山水":["江河"],"人物":["父亲"],"生活":["田园"]},"theme_conf":0.472},{"uid":"8040db71-8a96-49e2-9f4d-5417af0a0e3e","title":"送孔巢父谢病归游江东兼呈李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巢父掉头不肯住，东将入海随烟雾。","诗卷长流天地间，钓竿欲拂珊瑚树。","深山大泽龙蛇远，春寒野阴风景暮。","蓬莱织女回云车，指点虚无是征路。","自是君身有仙骨，世人那得知其故。","惜君只欲苦死留，富贵何如草头露。","蔡侯静者意有余，清夜置酒临前除。","罢琴惆怅月照席，几岁寄我空中书。","南寻禹穴见李白，道甫问信今何如。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡","豪放"],"mood":"孤寂","mood2":["惆怅"],"scene":["酒","江","七夕"],"cats":{"抒情":["感恩"],"人物":["父亲"],"节日":["七夕节"]},"theme_conf":0.415},{"uid":"4889a0b4-4921-4d09-bab3-b69ae5fb1f5b","title":"同辛衮州巢父虚副端岳相思献酬之作因纾归怀兼呈辛魏二院长杨长宁","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮角发高城，情人坐中起。","临觞不及醉，分散秋风里。","虽有明月期，离心若千里。","前欢反惆怅，后会还如此。","焉得夜淹留，一回终宴喜。","羇游复牵役，馆至重湖水。","早晚泛归舟，吾从数君子。"],"theme":"寄赠酬答","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["月","酒","园林"],"cats":{"抒情":["爱情","思念"],"天气":["月亮"],"人物":["父亲"]},"theme_conf":0.93},{"uid":"cpd4852635a024cd","title":"八声甘州","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对潇潇、暮雨洒江天，一番洗清秋。","渐霜风凄惨，关河冷落，残照当楼。","是处红衰翠减，苒苒物华休。","惟有长江水，无语东流。","不忍登高临远，望故乡渺邈，归思难收。","叹年来踪迹，何事苦淹留。","想佳人、妆楼望，误几回、天际识归舟。","争知我、倚阑干处，正恁凝愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"山水":["长江"],"人物":["女子"]},"theme_conf":1.0},{"uid":"bdf49a1c-c6fe-4239-8607-8007bc43bc24","title":"吐绶鸟词","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["越山有鸟翔寥廓，嗉中天绶光若若。","越人偶见而奇之，因名吐绶江南知。","四明天姥神仙地，朱鸟星精钟异气。","赤玉雕成彪炳毛，红绡翦出玲珑翅。","湖烟始开山日高，迎风吐绶盘花绦。","临波似染瑯琊草，映叶疑开阿母桃。","花红草绿人间事，未若灵禽自然贵。","鹤吐明珠暂报恩，鹊衔金印空为瑞。","春和秋霁野花开，玩景寻芳处处来。","翠幕雕笼非所慕，珠丸柘弹莫相猜。","栖月啼烟凌缥缈，高林先见金霞晓。","三山仙路寄遥情，刷羽扬翘欲上征。","不学碧鸡依井络，愿随青鸟向层城。","太液池中有黄鹄，怜君长向高枝宿。","如何一借羊角风，来听箫韶九成曲。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["鸟","江南"],"cats":{"人物":["母亲"]},"theme_conf":1.0},{"uid":"fc1ccfae-5091-4e0a-9b84-2e2cdecd6f78","title":"虹藏不见","author":"徐敞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迎冬小雪至，应节晚虹藏。","玉气徒成象，星精不散光。","美人初比色，飞鸟罢呈祥。","石涧收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎残阳。","舒卷应时令，因知圣历长。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["雨","冬","雪"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.96},{"uid":"f7f4ec54-5d81-4fd5-8eef-abf0908ed971","title":"赋得亚父碎玉斗","author":"孟简","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["献谋既我违，积愤从心痗。","鸿门入已迫，赤帝时潜退。","宝位方苦竞，玉斗何情爱。","犹看虹气凝，讵惜冰姿碎。","而嗟大事返，当起千里悔。","谁为西楚王，坐见东城溃。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"人物":["父亲"]},"theme_conf":0.693},{"uid":"cpeb9e1e9caece13","title":"永遇乐","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月如霜，好风如水，清景无限。","曲港跳鱼，圆荷泻露，寂寞无人见。","如三鼓，铿然一叶，黯黯梦云惊断。","夜茫茫，重寻无处，觉来小园行遍。","天涯倦客，山中归路，望断故园心眼。","燕子楼空，佳人何在，空锁楼中燕。","古今如梦，何曾梦觉，但有旧欢新怨。","异时对，黄楼夜景，为余浩叹。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["月","楼","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.763},{"uid":"620190f9-ce46-4ac0-979a-2926f377fb5a","title":"和杜录事题红叶","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒山十月旦，霜叶一时新。","似烧非因火，如花不待春。","连行排绛帐，乱落剪红巾。","解驻篮轝看，风前唯两人。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花","春"],"cats":{"四季":["春天"],"人物":["老师"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"5aa3def9-8feb-467b-9f28-84df62f0c714","title":"喜钱左丞再除华州以诗伸贺","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["左辖辍中台，门东委上才。","彤襜经宿到，绛帐及春开。","民望恳难夺，天心慈易回。","那知不隔岁，重借寇恂来。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["老师"]},"theme_conf":0.96},{"uid":"65d1fa84-153c-4a45-95da-f90cb66f36a5","title":"寄禅师寺华上人次韵三首 三","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["德士名难避，风流学济颠。","礼罗加璧至，荐鹗与云连。","尘世休飞锡，松林且枕泉。","近闻离讲席，听雨半山眠。"],"theme":"哲理悟道","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","山"],"cats":{"人物":["老师"],"人生":["哲理"]},"theme_conf":0.524},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"e961ac8e-2de7-4ba1-a5a4-e1b810809edf","title":"片玉篇","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至宝未为代所奇，韫灵示[璞]荆山陲。","独使虹光天子识，不将清韵世人知。","世人所贵惟燕石，美玉对之成瓦砾。","空山埋照凡几年，古色苍痕宛自然。","重溪幂幂暗云树，一片荧荧光石泉。","美人之鉴明且彻，玉指提携叹奇绝。","试劳香袖拂莓苔，不觉清心皎冰雪。","连城美价幸逢时，命代良工岂见遗。","试作珪璋礼天地，何如瓀𤨟在堦墀。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":[],"scene":["冬","雪","山"],"cats":{"抒情":["孤独"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"cb457f4a-a49c-46cc-becf-d4419d617b79","title":"玉华宫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["溪回松风长，苍鼠窜古瓦。","不知何王殿，遗构绝壁下。","阴房鬼火青，坏道哀湍泻。","万籁真笙竽，秋色正萧洒。","美人为黄土，况乃粉黛假。","当时侍金舆，故物独石马。","忧来藉草坐，浩歌泪盈把。","冉冉征途间，谁是长年者。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋"],"cats":{"抒情":["伤感","孤独","悼亡"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.516},{"uid":"f8055804-4c69-4e9d-b63c-d649c86a6b5f","title":"奉汉中王手札报韦侍御萧尊师亡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日萧韦逝，淮王报峡中。","少年疑柱史，多术怪仙公。","不但时人惜，祗应吾道穷。","一哀侵疾病，相识自儿童。","处处邻家笛，飘飘客子蓬。","强吟怀旧赋，已作白头翁。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["悼亡"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.98},{"uid":"891b2c80-f3fc-4841-93a9-6d68605e175a","title":"燕衔泥","author":"冯著","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双燕碌碌飞入屋，屋中老人喜燕归。","裴回绕我床头飞，去年为尔逐黄雀。","雨多屋漏泥土落，尔莫厌老翁茅屋低，梁头作窠梁下栖。","尔不见东家黄鷇鸣啧啧，蛇盘瓦沟鼠穿壁。","豪家大屋尔莫居，娇儿少妇采尔雏。","井旁写水泥自足，衔泥上屋随尔欲。"],"theme":"亲情","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟"],"cats":{"人物":["儿童"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"f1befe2e-2e4d-4220-aa06-5fae1d3a1a04","title":"送王绪剡中","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不见关山去，何时到郯中。","已闻成竹木，更道长儿童。","篱落云常聚，村墟水自通。","朝朝忆玄度，非是对清风。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外","山"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.592},{"uid":"1e5d503c-12ee-4e2c-a645-80e5e892316b","title":"赠薛戴","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓雾忽为霜，寒蝉还罢响。","行人在长道，日暮多归想。","射策本何功，名登绛帐中。","遂矜丘室重，不料阮途穷。","交结慙时辈，龙钟似老翁。","机非鄙夫正，懒是平生性。","欹枕鸿雁高，闭关花药盛。","厨烟当雨绝，阶竹连窗暝。","欲赋苦饥行，无如消渴病。","旧业历胡尘，荒原少四邻。","田园空有处，兄弟未成人。","毛义心长苦，袁安家转贫。","今呈胸臆事，当为泪沾巾。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["老师"],"生活":["田园"]},"theme_conf":0.96},{"uid":"cca28bc8-2689-4419-bf3b-e5fef10f5db5","title":"横吹曲辞 长安道","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["花枝缺处青楼开，艳歌一曲酒一杯。","美人劝我急行乐，自古朱颜不再来。","君不见外州客，长安道，一回来，一回老。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人物":["女子"]},"theme_conf":0.65},{"uid":"2c08a55b-3506-4770-a3fb-66b0d021835e","title":"奉贺阳城郡王太夫人恩命加邓国太夫人","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["卫幕衔恩重，潘舆送喜频。","济时瞻上将，锡号戴慈亲。","富贵当如此，尊荣迈等伦。","郡依封土旧，国与大名新。","紫诰鸾回纸，清朝燕贺人。","远传冬笋味，更觉彩衣春。","奕叶班姑史，芬芳孟母邻。","义方兼有训，词翰两如神。","委曲承颜体，骞飞报主身。","可怜忠与孝，双美画骐麟。"],"theme":"送别","theme2":["应制干谒"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","春"],"cats":{"四季":["春天","冬天"],"人物":["母亲"]},"theme_conf":0.51},{"uid":"7a6e1b7d-494b-4ffe-94ac-2b69f9784f35","title":"江涨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江涨柴门外，儿童报急流。","下床高数尺，倚杖没中洲。","细动迎风燕，轻摇逐浪鸥。","渔人萦小楫，容易拔船头。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"c269dec4-e6e7-40b3-b1c5-b371d0450eb0","title":"怀素上人草书歌","author":"窦冀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狂僧挥翰狂且逸，独任天机摧格律。","龙虎惭因点画生，雷霆却避锋铓疾。","鱼牋娟素岂不贵，只嫌局促儿童戏。","粉壁长廊数十间，兴来小豁胸襟气。","长幼集，贤豪至，枕糟藉曲犹半醉。","忽然绝叫三五声，满壁纵横千万字。","吴兴张老尔莫颠，叶县公孙我何谓。","如熊如罴不足比，如虺如蛇不足拟。","涵物为动鬼神泣，狂风入林花乱起。","殊形怪状不易说，就中惊燥尤枯绝。","边风杀气同惨烈，崩槎卧木争摧折。","塞草遥飞大漠霜，胡天乱下阴山雪。","偏看能事转新奇，郡守王公同赋诗。","枯藤劲铁媿三舍，骤雨寒猨惊一时。","此生绝艺人莫测，假此常为护持力。","连城之璧不可量，五百年知草圣当。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"孤寂","mood2":["悲怆"],"scene":["雪","塞外"],"cats":{"抒情":["孤独"],"天气":["写风","写雨"],"人物":["儿童"],"生活":["边塞"]},"theme_conf":0.773},{"uid":"4365fdc6-9e89-489c-abe1-4eda95a85062","title":"杂曲歌辞 升天行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["身不沈，骨不重，驱青鸾，驾白凤。","幢盖飘飘入冷空，天风瑟瑟星河动。","瑶阙参差阿母家，楼台戏闭凝彤霞。","五三仙子乘龙车，堂前碾烂蟠桃花。","回头却顾蓬山顶，一点浓岚在深井。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"天气":["星星"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"4cf19354-4c0a-4e55-980b-69fa7f81ed0f","title":"游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"afa0d6db-b93a-4e96-aae9-59ec920eb6de","title":"杂曲歌辞 游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故巢思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰晖百年内，惟愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何艰哉？北斗不可斟。","夜晴星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蜻蛚催寒砧。","立身计几误，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧因古今。","胡为不归欤，孤负丘中琴。","腰下是何物？牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山杳岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾霄汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分堙沈。","层城发云韶，玉府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋","江","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.291},{"uid":"ba2f4924-7ab8-48f2-9e23-d656dea0117b","title":"杂曲歌辞 行路难二首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["长安少年不少钱，能骑骏马鸣金鞭。","五侯相逢大道边，美人弦管争留连。","黄金如斗不敢惜，片言如山莫弃捐。","安知顦顇读书者，暮宿虚台私自怜。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["读书"]},"theme_conf":0.65},{"uid":"3c6b2b9c-7570-4a5a-8635-1857e0a01c9b","title":"别青州妓段东美 二","author":"薛宜僚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母桃花方似锦，王孙草色正如烟。","不须更向沧溟望，惆怅欢情恰一年。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":[],"cats":{"抒情":["离别"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"ab4b1a7f-4fbe-438b-817f-9e1ed2d39f4f","title":"宫词","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["寂寂花时闭院门，美人相并立琼轩。","含情欲说宫中事，鹦鹉前头不敢言。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林"],"cats":{"抒情":["闺怨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"5d8662c6-50dd-419b-b0d6-bacb6a227026","title":"问张山人疾","author":"李端","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["先生沈病意何如，蓬艾门前客转疎。","不见领徒过绛帐，唯闻与婢削丹书。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人物":["老师"]},"theme_conf":1.0},{"uid":"cf68f337-d8fc-48a3-b89e-a828d08189a6","title":"喜观即到复题短篇二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["巫峡千山暗，终南万里春。","病中吾见弟，书到汝为人。","意荅儿童问，来经战伐新。","泊船悲喜后，款款话归秦。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放","沉郁"],"mood":"欢愉","mood2":[],"scene":["春","舟","山"],"cats":{"四季":["春天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.65},{"uid":"ee3195f6-eb17-4e87-b714-f7cf07ff03f2","title":"鼓吹曲辞 上之回","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三十六离宫，楼台与天通。","阁道步行月，美人愁烟空。","恩疎宠不及，桃李伤春风。","淫乐意何极，金舆向回中。","万乘出黄道，千旗扬彩虹。","前军细柳北，后骑甘泉东。","岂问渭川老，宁邀襄野童。","秋暮瑶池宴，归来乐未穷。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.538},{"uid":"7e29d72b-7386-48c6-af3c-9dafd02f0665","title":"木兰歌","author":"韦元甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["木兰抱杼嗟，借问复为谁。","欲闻所戚戚，感激彊其颜。","老父隶兵籍，气力日衰耗。","岂足万里行，有子复尚少。","胡沙没马足，朔风裂人肤。","老父旧羸病，何以彊自扶。","木兰代父去，秣马备戎行。","易却纨绮裳，洗却铅粉妆。","驰马赴军幕，慷慨携干将。","朝屯雪山下，暮宿青海傍。","夜袭燕支虏，更携于阗羌。","将军得胜归，士卒还故乡。","父母见木兰，喜极成悲伤。","木兰能承父母颜，却卸巾鞲理丝簧。","昔为烈士雄，今为娇子容。","亲戚持酒贺父母，始知生女与男同。","门前旧军都，十年共崎岖。","本结弟兄交，死战誓不渝。","今者见木兰，言声虽是颜貌殊。","惊愕不敢前，叹息徒嘻吁。","世有臣子心，能如木兰节。","忠孝两不渝，千古之名焉可灭。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放","悲慨"],"mood":"悲怆","mood2":["慷慨"],"scene":["冬","夜","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"天气":["写风"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.668},{"uid":"215dbf70-fc96-41e5-80ae-edf233df30e1","title":"杂曲歌辞 出门行二首 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["海风萧萧天雨霜，穷愁独坐夜何长？","驱车旧忆太行险，始知游子悲故乡。","美人相思隔天阙，长望云端不可越。","手持琅玕欲有赠，爱而不见心断绝。","南山峨峨白石烂，碧海之波浩漫漫。","参辰出没不相待，我欲横天无羽翰。"],"theme":"羁旅思乡","theme2":["爱情相思","送别","亲情"],"style":"幽峭","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["雨","夜"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"人物":["女子"]},"theme_conf":0.319},{"uid":"d4baf2d1-ea61-4fb3-a284-e889275bdca2","title":"杂曲歌辞 长相思三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井栏。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有绿水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"2446f3e6-9a1f-465f-9cba-e481a62e956d","title":"暮春游长沙东湖赠辛兖州巢父二首 一","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["湘流分曲浦，缭绕古城东。","岸转千家合，林开一镜空。","人生无事少，心赏几回同。","且复忘羁束，悠悠落照中。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.88},{"uid":"fd70c9ee-2527-43d0-89f6-a32bd4a3aa03","title":"题山居","author":"曹邺","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["扫叶煎茶摘叶书，心闲无梦夜窗虚。","只应光武恩波晚，岂是严君恋钓鱼。"],"theme":"闲适隐逸","theme2":["闲适隐逸","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","夜"],"cats":{"人物":["父亲"]},"theme_conf":0.85},{"uid":"bdd79ce6-205b-4c91-bf73-532087f5acfe","title":"杂曲歌辞 空城雀","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["空城雀，何不飞来人家住？","空城无人种禾黍。","土间生子草间长，满地蓬蒿幸无主。","近村虽有高树枝，雨中无食长苦饥。","八月小儿夹弓箭，家家畏我田头飞。","但能不出空城里，秋时百草皆有子。","黄口黄口莫啾啾，长尔得成无横死。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","雨","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.522},{"uid":"2d7db01d-48b4-4f83-8627-41b98b7321a9","title":"相和歌辞 陌上桑","author":"常建","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蚕饥，盈盈娇路傍。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"人物":["女子"]},"theme_conf":0.532},{"uid":"c7e721a1-9169-46c6-bbf3-970fef076539","title":"相和歌辞 铜雀妓","author":"刘商","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["魏主矜蛾眉，美人美于玉。","高台无昼夜，歌舞竟未足。","盛色如转圜，夕阳落深谷。","仍令身殁后，尚足平生欲。","红粉横泪痕，调弦空向屋。","举头君不在，唯见西陵木。","玉辇岂再来，娇鬟为谁绿。","那堪秋风里，更舞阳春曲。","曲终情不胜，阑干向西哭。","台边生野草，来去罥罗縠。","况复陵寝间，双双见麋鹿。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["绮丽","沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","夜","秋","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天","秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"de37c5eb-9420-4c1d-a0a8-e9d9a5a118ca","title":"杂曲歌辞 少年行","author":"韦庄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["五陵豪客多，买酒黄金贱。","醉下酒家楼，美人双翠幰。","挥劒邯郸市，走马梁王苑。","乐事殊未央，年华已云晚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["青春"]},"theme_conf":0.654},{"uid":"1a811379-9526-4288-bde8-5c1e150eb96a","title":"赠女道士郑玉华二首 二","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["明镜湖中休采莲，却师阿母学神仙。","朱丝误落青囊里，犹是箜篌第几弦。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":0.86},{"uid":"bbbbba72-14ae-42d1-9f5a-09a077f2d0c6","title":"最能行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["峡中丈夫绝轻死，少在公门多在水。","富豪有钱驾大舸，贫穷取给行艓子。","小儿学问止论语，大儿结束随商旅。","攲帆侧柁入波涛，撇漩捎𣸣无险阻。","朝发白帝暮江陵，顷来目击幸有征。","瞿堂漫天虎须怒，归州长年行最能。","此乡之人气量窄，误竞南风疎北客。","若道土无英俊才，何得山有屈原宅。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["舟","端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"c8bae0f0-12c6-4d6c-a35d-7077217cfdea","title":"南邻","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["锦里先生乌角巾，园收芋粟不全贫。","惯看宾客儿童喜，得食阶除鸟雀驯。","秋水才深四五尺，野航恰受两三人。","白沙翠竹江村暮，相对柴门月色新。"],"theme":"寄赠酬答","theme2":["山水田园","送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["月","夜"],"cats":{"天气":["月亮"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.72},{"uid":"8e4f53da-0190-413d-9c18-f8043d90e2be","title":"送幽州陈参军赴任寄呈乡曲父老","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蓟北三千里，关西二十年。","冯唐犹在汉，乐毅不归燕。","人同黄鹤远，乡共白云连。","郭隗池台处，昭王尊酒前。","故人当已老，旧壑几成田。","红颜如昨日，衰鬓似秋天。","西蜀桥应毁，东周石尚全。","灞池水犹绿，榆关月早圆。","塞云初上雁，庭树欲销蝉。","送君之旧国，挥泪独澘然。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["鸟","园林","秋"],"cats":{"抒情":["友情","离别","伤感","孤独"],"四季":["秋天"],"人物":["父亲"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"60f3c484-4e4f-4612-9f93-e753c7c67c02","title":"送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁脔去东床，趋庭赴北堂。","风波空远涉，琴瑟几虚张。","渥水出骐骥，昆山生凤皇。","两家诚款款，中道许苍苍。","颇谓秦晋匹，从来王谢郎。","青春动才调，白首缺辉光。","玉润终孤立，珠明得暗藏。","余寒折花卉，恨别满江乡。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["女子","父亲"],"人生":["青春"]},"theme_conf":0.524},{"uid":"8c257f77-fbd5-4f89-a01d-f069cc2189b2","title":"杂曲歌辞 悲哉行","author":"孟云卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤儿去慈亲，远客丧主人。","莫吟苦辛曲，谁忍闻可闻。","可闻不可说，去去无期别。","行人念前程，不待参辰没。","朝亦常苦饥，暮亦常苦饥。","飘飘万余里，贫贱多是非。","少年莫远游，远游多不归。"],"theme":"羁旅思乡","theme2":["民生疾苦"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感"],"人物":["母亲"]},"theme_conf":0.402},{"uid":"2d69a74c-1dad-46c4-a6d8-78d56d12145d","title":"东郊纳凉忆左威卫李录事收昆季太原崔参军三首 二","author":"楼颕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纳凉每选地，近得青门东。","林与缭垣接，池将沁水通。","枝交帝女树，桥映美人虹。","想是忘机者，悠悠在兴中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["恬淡"],"scene":[],"cats":{"抒情":["思念"],"山水":["庐山"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.695},{"uid":"cd3d8e0c-a549-44a9-b55c-4f1c9b9befed","title":"秋霖中奉裴令公见招早出赴会马上先寄六韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是寻医药，非干送别离。","素书传好语，绛帐赴佳期。","续借桃花马，催迎杨柳姬。","只愁张录事，罚我怪来迟。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写雨"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.88},{"uid":"5849dc58-0b5b-4181-ad61-285eb6ca25f5","title":"秋思","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋室浩烟雾，风柳怨寒蜩。","机杼夜声切，蕙兰芳意消。","美人湘水曲，桂檝洞庭遥。","常恐时光谢，蹉跎红艳凋。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["女子"],"人生":["时光"]},"theme_conf":1.0},{"uid":"f3c25a75-6445-47e0-a5ae-265559f9f990","title":"越燕二首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["将泥红蓼岸，得草绿杨村。","命侣添新意，安巢复旧痕。","去应逢阿母，来莫害王孙。","记取丹山凤，今为百鸟尊。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","江南"],"cats":{"人物":["母亲"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"e953a74d-4075-48bb-928f-114d0cd1a9eb","title":"哭单父梁九少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["开箧泪沾臆，见君前日书。","夜台今寂寞，独是子云居。","畴昔探云奇，登临赋山水。","同舟南浦下，望月西江里。","契阔多别离，绸缪到生死。","九原即何处，万事皆如此。","晋山徒峨峨，斯人已冥冥。","常时禄且薄，殁后家复贫。","妻子在远道，弟兄无一人。","十上多苦辛，一官恒自哂。","青云将可致，白日忽先尽。","唯有身后名，空留无远近。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["悲怆"],"scene":["舟","山"],"cats":{"抒情":["离别","伤感","孤独","悼亡"],"人物":["父亲"]},"theme_conf":0.371},{"uid":"1b39ff1f-95d3-43b6-ad22-561c8e97f329","title":"王十五前阁会","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚岸收新雨，春台引细风。","情人来石上，鲜脍出江中。","邻舍烦书札，肩舆强老翁。","病身虚俊味，何幸饫儿童。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"人物":["儿童"]},"theme_conf":0.72},{"uid":"2618397e-f65f-4680-9751-f0f1e2ce2533","title":"奉和荥阳公离筵作","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["南郡生徒辞绛帐，东山妓乐拥油旌。","钧天排比箫韶待，犹顾人间有别情。"],"theme":"应制干谒","theme2":["送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人物":["老师"]},"theme_conf":0.76},{"uid":"92786fed-bd1f-4b19-bbe1-145d5120f253","title":"送温况游蜀","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["游人西去客三巴，身逐孤蓬不定家。","山近峨眉飞暮雨，江连濯锦起朝霞。","云深九折刀州远，路绕千岩剑阁斜。","应到严君开卦处，将余一为问生涯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["山","雨"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.501},{"uid":"982aa516-163c-40fd-94ab-3c7c743456c9","title":"遣意二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["簷影微微落，津流脉脉斜。","野船明细火，宿鴈聚圆沙。","云掩初弦月，香传小树花。","邻人有美酒，稚子夜能赊。"],"theme":"亲情","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花","酒","舟","月","夜"],"cats":{"人物":["儿童"]},"theme_conf":0.571},{"uid":"276d7c1f-d89d-48fd-a8f5-777b9efd9d23","title":"酬秘书弟兼寄幕下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["亚相膺时杰，群才遇良工。","翩翩幕下来，拜赐甘泉宫。","信知命世奇，适会非常功。","侍御执邦宪，清词焕春丛。","末路望绣衣，他时常发蒙。","孰云三军壮，惧我弹射雄。","谁谓万里遥，在我樽俎中。","光禄经济器，精微自深衷。","前席屡荣问，长城兼在躬。","高纵激颓波，逸翮驰苍穹。","将副节制筹，欲令沙漠空。","司业志应徐，雅度思冲融。","相思三十年，忆昨犹儿童。","今来抱青紫，忽若披鹓鸿。","说劒增慷慨，论交持始终。","秘书即吾门，虚白无不通。","多才陆平原，硕学郑司农。","献封到关西，独步归山东。","永意久知处，嘉言能亢宗。","客从梁宋来，行役随转蓬。","酬赠欣元弟，忆贤瞻数公。","游鳞戏沧浪，鸣凤栖梧桐。","并负垂天翼，俱乘破浪风。","眈眈天府间，偃仰谁敢同。","何意搆广厦，翻然顾雕虫。","应知阮步兵，惆怅此途穷。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["塞外"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["励志"]},"theme_conf":0.95},{"uid":"7f1258da-f56c-4485-aea5-e405a6ce4997","title":"题桃树","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["小径升堂旧不斜，五株桃树亦从遮。","高秋总𫗪贫人实，来岁还舒满眼花。","帘户每宜通乳燕，儿童莫信打慈鵶。","寡妻群盗非今日，天下车书正一家。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"869a90a2-6d0b-4c59-90c4-f6c2ec8ab6b6","title":"暮春游长沙东湖赠辛兖州巢父二首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["回环路不尽，历览意弥新。","古木畬田火，澄江荡桨人。","缓歌寻极浦，一醉送残春。","莫恨长沙远，他年忆此辰。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江"],"cats":{"抒情":["思念"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"6bb1ee39-265a-4c53-a5b4-311b2e65429c","title":"和荅弟志和渔父歌","author":"张松龄","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乐是风波钓是闲，草堂松径已胜攀。","太湖水，洞庭山，狂风浪起且须还。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["江"],"cats":{"天气":["写风"],"人物":["父亲"],"人生":["梦想"]},"theme_conf":0.598},{"uid":"6c49fcc2-e014-4a5f-8b7b-bc592de83062","title":"遭田父泥饮美严中丞","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["步屧随春风，邨邨自花柳。","田翁逼社日，邀我尝春酒。","酒酣夸新尹，畜眼未见有。","回头指大男，渠是弓弩手。","名在飞骑籍，长番岁时久。","前日放营农，辛苦救衰朽。","差料死则已，誓不举家走。","今年大作社，拾遗能住否。","叫妇开大缾，盆中为吾取。","感此气扬扬，须知风化首。","语多虽杂乱，说尹终在口。","朝来偶然出，自卯将及酉。","久客惜人情，如何拒邻叟。","高声索果栗，欲起时被肘。","指挥过无礼，未觉邨野丑。","月出遮我留，仍嗔问升斗。"],"theme":"应制干谒","theme2":["山水田园","节令风俗","羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.62},{"uid":"d179b5ca-f7ba-4b1b-8dae-311ef942a6e0","title":"舞曲歌辞 白纻歌二首 二","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["馆娃宫中春日暮，荔枝木瓜花满树。","城头乌栖休击鼓，青娥弹瑟白纻舞。","夜天燑燑不见星，宫中火照西江明。","美人醉起无次第，堕钗遗佩满中庭。","此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。"],"theme":"闺情宫怨","theme2":[],"style":"旷达","style2":[],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人物":["女子"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"cpe122a2a80234ea","title":"绿头鸭・多丽","author":"晁端礼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚云收，淡天一片琉璃。","烂银盘、来从海底，皓色千里澄辉。","莹无尘、素娥淡伫，静可数、丹桂参差。","玉露初零，金风未凛，一年无似此佳时。","露坐久，疏莹时度，乌鹊正南飞。","瑶台冷，栏干凭暖，玉下迟迟。","念佳人，音尘别后，对此应解相思。","最关情、漏声正永，暗断肠、花影偷移。","料得来宵，清光未减，阴晴天气又争知。","共凝恋、如今别后，还是隔年期。","人强健，清尊素影，长愿相随。"],"theme":"送别","theme2":["爱情相思","游仙梦幻"],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["恬淡"],"scene":["夜"],"cats":{"抒情":["爱情","思念"],"人物":["女子"]},"theme_conf":0.351},{"uid":"cp535eb913df2263","title":"洞仙歌","author":"晁补之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青烟幂处，碧海飞金镜。","永夜闲阶卧桂影。","露凉时、零乱多少寒，神京远，惟有蓝桥路近。","水晶帘不下，云母屏开，冷浸佳人淡脂粉。","待都将许多明，付与金尊，投晓共、流霞倾尽。","更携取、胡床上南楼，看玉做人间，素秋千倾。"],"theme":"游仙梦幻","theme2":["边塞征战"],"style":"冲淡","style2":["绮丽","清新"],"mood":"恬淡","mood2":[],"scene":["夜","秋","楼"],"cats":{"四季":["秋天"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.547},{"uid":"edeba321-b6dc-4573-b3d9-6e5d1ac95d0c","title":"将之泸郡旅次遂州遇裴晤员外谪居于此话旧凄凉因寄二首 二","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔年共照松溪影，松折溪荒僧已无。","今日重思锦城事，雪销花谢梦何殊。","乱离未定身俱老，骚雅全休道甚孤。","我拜师门更南去，荔枝春熟向渝泸。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"人物":["老师"],"食物":["荔枝"]},"theme_conf":0.92},{"uid":"18734c96-6ba5-4e4d-9150-fa5d31b646d9","title":"晚次新丰北野老家书事呈赠韩质明府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["机鸣舂响日暾暾，鸡犬相和汉古村。","数派清泉黄菊盛，一林寒露紫棃繁。","衰翁正席矜新社，稚子齐襟读古论。","共说年来但无事，不知何者是君恩。"],"theme":"山水田园","theme2":["山水田园","羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.68},{"uid":"8399a509-3f09-4027-a389-f5c4ba9e5dfe","title":"送李翺习之","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["习之势翩翩，东南去遥遥。","赠君双履足，一为上臯桥。","臯桥路逶迤，碧水清风飘。","新秋折藕花，应对吴语娇。","千巷分渌波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齿痕，有处应未销。","旧忆如雾星，怳见于梦消。","言之烧人心，事去不可招。","独孤宅前曲，箜篌醉中谣。","壮年俱悠悠，逮兹各焦焦。","执手复执手，唯道无枯凋。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["老师"],"生活":["写桥"]},"theme_conf":0.8},{"uid":"569ef0e1-887d-4d98-b869-9634f099c8e9","title":"还乡偶书  其二","author":"黄拱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["少小离家老大回，乡音难改鬓毛衰。","儿童相见不相识，借问客从何处来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":[],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.883},{"uid":"029ff16c-6562-4d06-95d9-765045b30c69","title":"新桃行","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["桃生叶婆娑，枝叶四向多。","高未出墙颠，蒿苋相凌摩。","植之三年余，今年初试花。","秋来已成实，其阴良已嘉。","青蝉不来鸣，安得迅羽过。","常恶牵丝虫，蒙幂成网罗。","顾托戏儿童，勿折吾柔柯。","明年结其实，磊磊充汝家。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"5a27558b-ebcb-4073-a6fa-fe619881a570","title":"擢第后东归书怀献座主吕侍御","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔岁辞亲泪，今为恋主泣。","去住情难竝，别离景易戢。","夭矫大空鳞，曾为小泉蛰。","幽意独沈时，震雷忽相及。","神行既不宰，直致非所执。","至运本遗功，轻生各自立。","大君思此化，良佐自然集。","宝镜无私光，时文有新习。","慈亲诫志就，贱子归情急。","擢第谢灵台，牵衣出皇邑。","行襟海日曙，逸抱江风入。","蒹葭得波浪，芙蓉红岸湿。","云寺势动摇，山钟韵嘘吸。","旧游期再践，悬水得重挹。","松萝虽可居，青紫终当拾。"],"theme":"应制干谒","theme2":["山水田园","闲适隐逸"],"style":"婉约","style2":["冲淡"],"mood":"孤寂","mood2":["悲怆"],"scene":[],"cats":{"抒情":["离别","伤感","孤独"],"人物":["母亲"]},"theme_conf":0.85},{"uid":"0e42b61d-d0b4-4876-bfbd-269008daa0f8","title":"北游还酬孟云卿","author":"张彪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忽忽忘前事，志愿能相乖。","衣马久羸弊，谁信文与才。","善道居贫贱，洁服蒙尘埃。","行行无定心，𡒄坎难归来。","慈母忧疾疹，至家念栖哀。","与君宿姻亲，深见中外怀。","俟余惜时节，伥望临高台。"],"theme":"寄赠酬答","theme2":["亲情"],"style":"婉约","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":[],"cats":{"抒情":["感恩"],"人物":["母亲"]},"theme_conf":0.84},{"uid":"d48cdb59-2492-497b-a8c3-11a3930448bb","title":"罗浮山父与葛篇","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["依依宜织江雨空，雨中六月兰台风。","博罗老仙时出洞，千岁石床啼鬼工。","蛇毒浓凝洞堂湿，江鱼不食衔沙立。","欲剪箱中一尺天，吴娥莫道吴刀涩。"],"theme":"亲情","theme2":["山水田园"],"style":"幽峭","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["山","雨","江","江南","月"],"cats":{"人物":["父亲"],"植物":["梅花"]},"theme_conf":0.506},{"uid":"06bb6ddd-5f47-42f0-a020-b7671ad56bdf","title":"相和歌辞 短歌行六首 四","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["何处春风吹晓幕？江南绿水通朱阁。","美人二八面如花，泣向东风畏花落。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["春","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.65},{"uid":"82166154-7317-4617-a50c-a9a5a2896da3","title":"杂曲歌辞 伤歌行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄门诏下促收捕，京兆君系御史府。","出门无复部曲随，亲戚相逢不容语。","辞成谪尉南海州，受命不得须臾留。","身著青衫骑恶马，东门之东无送者。","邮夫防吏急喧驱，往往惊堕马蹏下。","长安里中荒大宅，朱门已除十二戟。","高堂舞榭锁管弦，美人遥望西南天。"],"theme":"送别","theme2":["悼亡挽歌","讽喻刺世"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["伤感","悼亡"],"人物":["女子"]},"theme_conf":0.381},{"uid":"511b0ab5-253f-4f98-b82e-6029d875abcf","title":"重题","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["涕泗不能收，哭君余白头。","儿童相识尽，宇宙此生浮。","江雨铭旌湿，湖风井径秋。","还瞻魏太子，宾客减应刘。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江","秋","雨"],"cats":{"四季":["秋天"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"ef96daf2-7596-4663-8431-901daf08fafa","title":"美人尝茶行","author":"崔珏","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云鬟枕落困春泥，玉郎为碾瑟瑟尘。","闲教鹦鹉啄窗响，和娇扶起浓睡人。","银瓶贮泉水一掬，松雨声来乳花熟。","朱唇啜破绿云时，咽入香喉爽红玉。","明眸渐开横秋水，手拨丝簧醉心起。","台时却坐推金筝，不语思量梦中事。"],"theme":"爱情相思","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["花","春","秋","雨"],"cats":{"四季":["春天","秋天"],"人物":["女子"],"食物":["写茶"]},"theme_conf":0.62},{"uid":"757a180d-55eb-4931-9f10-c71649f6a06d","title":"秋日过鸿举法师寺院便送归江陵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["看画长廊遍，寻僧一径幽。","小池兼鹤净，古木带蝉秋。","客至茶烟起，禽归讲席收。","浮杯明日去，相望水悠悠。"],"theme":"送别","theme2":["咏史怀古","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"动物":["写鸟"]},"theme_conf":0.28},{"uid":"09788f19-1e11-4394-a543-0edf2cfdcae9","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":["塞外"],"cats":{"抒情":["离别","思念","伤感","孤独"],"人物":["女子"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.755},{"uid":"72366286-73aa-49c3-9ac0-fa0017da8a4a","title":"王可封临终","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十世为儒少子孙，一生长负信陵恩。","今朝埋骨寒山下，为报慈亲休倚门。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"7b9b330b-4d3f-4de9-96bd-610bdd918133","title":"射训狐","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有鸟夜飞名训狐，矜凶挟狡夸自呼。","乘时阴黑止我屋，声势慷慨非常麤。","安然大唤谁畏忌，造作百怪非无须。","聚鬼征妖自朋扇，摆掉栱桷颓塈涂。","慈母抱儿怕入席，那暇更护鸡窠雏。","我念乾坤德泰大，卵此恶物常勤劬。","纵之岂即遽有害，斗柄行拄西南隅。","谁谓停奸计尤剧，意欲唐突羲和乌。","侵更历漏气弥厉，何由侥幸休须臾。","咨余往射岂得已，候女两眼张睢盱。","枭惊堕梁蛇走窦，一夫斩颈群雏枯。"],"theme":"亲情","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["感恩"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"d9b26a58-c9cb-4a98-8980-32df48b58348","title":"代九九","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年桃李月，颜色共花宜。","廻脸莲初破，低蛾柳竝垂。","望山多倚树，弄水爱临池。","远被登楼识，潜因倒影窥。","隔林徒想像，上砌转逶迤。","谩掷庭中果，虚攀墙外枝。","强持文玉佩，求结麝香缡。","阿母怜金重，亲兄要马骑。","把将娇小女，嫁与冶游儿。","自隐勤勤索，相要事事随。","每常同坐卧，不省暂参差。","才学羞兼妒，何言宠便移。","青春来易皎，白日誓先亏。","僻性嗔来见，邪行醉后知。","别床铺枕席，当面指瑕疵。","妾貌应犹在，君情遽若斯。","的成终世恨，焉用此宵为。","鸾镜灯前扑，鸳衾手下隳。","参商半夜起，琴瑟一声离。","努力新丛艳，狂风次第吹。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["豪放","婉约"],"mood":"慷慨","mood2":["愁怨"],"scene":["园林","夜","春"],"cats":{"抒情":["离别","闺怨"],"四季":["春天"],"天气":["写风"],"人物":["母亲"],"人生":["青春"]},"theme_conf":0.431},{"uid":"5cee205e-5c59-46e5-b060-9b0916c64a3f","title":"忆昔二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔先皇巡朔方，千乘万骑入咸阳。","阴山骄子汗血马，长驱东胡胡走藏。","邺城反复不足怪，关中小儿坏纪纲，张后不乐上为忙。","至今今上犹拨乱，劳身焦思补四方。","我昔近侍叨奉引，出兵整肃不可当。","为留猛士守未央，致使岐雍防西羌。","犬戎直来坐御床，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"6ceea366-5fc7-4572-9da3-43f181a8dbbc","title":"寄妻父刘长卿","author":"李穆","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["处处云山无尽时，桐庐南望转参差。","舟人莫道新安近，欲上潺湲行自迟。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","山"],"cats":{"人物":["父亲"]},"theme_conf":0.9},{"uid":"4c57a579-0494-41cf-a174-6472ac4f2e8e","title":"游桃源一百韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["沅江清悠悠，连山郁岑寂。","回流抱绝𪩘，皎镜含虚碧。","昏旦递明媚，烟岚分委积。","香蔓垂绿潭，暴龙照孤碛。","渊明著前志，子骥思远跖。","寂寂无何乡，密尔天地隔。","金行太元岁，渔者偶探赜。","寻花得幽踪，窥洞穿暗隙。","依微闻鸡犬，豁达值阡陌。","居人互将迎，笑语如平昔。","广乐虽交奏，海禽心不怿。","挥手一来归，故溪无处觅。","绵绵五百载，市朝几迁革。","有路在壶中，无人知地脉。","皇家感至道，圣祚自天锡。","金阙传本枝，玉函留宝历。","禁山开秘宇，复户洁灵宅。","蘂检香氛氲，醮坛烟幂幂。","我来尘外躅，莹若朝星析。","崖转对翠屏，水穷留画鹢。","三休俯乔木，千级扳峭壁。","旭日闻撞钟，彩云迎蹑屐。","遂登最高顶，纵目还楚泽。","平湖见草青，远岸连霞赤。","幽寻如梦想，绵思属空阒。","夤缘且忘疲，耽玩近成癖。","清猨伺晓发，瑶草凌寒坼。","祥禽舞葱茏，珠树摇玓𬍛。","羽人顾我笑，劝我税归轭。","霓裳何飘飖，童颜洁白皙。","重岩是藩屏，驯鹿受羁靮。","楼居弥清霄，萝茑成翠帟。","仙翁遗竹杖，王母留桃核。","姹女飞丹砂，青童护金液。","宝气浮鼎耳，神光生劒脊。","虚无天乐来，僁窣鬼兵役。","丹丘肃朝礼，玉札工䌷绎。","枕中淮南方，床下阜乡舄。","明灯坐遥夜，幽籁听淅沥。","因话近世仙，耸然心神惕。","乃言瞿氏子，骨状非凡格。","往事黄先生，群儿多侮剧。","謷然不屑意，元气贮肝膈。","往往游不归，洞中观博弈。","言高未易信，犹复加诃责。","一旦前致辞，自云仙期迫。","言师有道骨，前事常被谪。","如今三山上，名字在真籍。","悠然谢主人，后岁当来觌。","言毕依庭树，如烟去无迹。","观者皆失次，惊追纷络绎。","日暮山径穷，松风自萧槭。","适逢修蛇见，瞋目光激射。","如严三清居，不使恣搜索。","唯余步纲势，八趾在沙砾。","至今东北隅，表以坛上石。","列仙徒有名，世人非目击。","如何庭庑际，白日振飞翮。","洞天岂幽远，得道如咫尺。","一气无死生，三光自迁易。","因思人间世，前路何狭窄。","瞥然此生中，善祝期满百。","大方播群类，秀气肖翕辟。","性静本同和，物牵成阻厄。","是非鬬方寸，荤血昏精魄。","遂令多夭伤，犹喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安缇绣荣，不悟泥途适。","纷吾本孤贱，世业在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰荐，乡曲缪推择。","居安白社贫，至傲玄𫄸辟。","功名希自取，簪组俟扬历。","书府蚤怀铅，射宫曾发的。","起草香生帐，坐曹乌集柏。","赐燕聆箫韶，侍祠阅琮璧。","尝闻履忠信，可以行蛮貊。","自述希古心，忘恃干时画。","巧言忽成锦，苦志徒食蘗。","平地生峰峦，深心有矛戟。","层波一震荡，弱植忽沦溺。","北渚吊灵均，长岑思亭伯。","祸来昧几兆，事去空叹息。","尘累与时深，流年随漏滴。","才能疑木鴈，报施迷夷跖。","楚奏絷钟仪，商歌劳宁戚。","禀生非悬解，对镜方感激。","自从婴网罗，每事问龟策。","王正降雷雨，环玦赐迁斥。","倘伏夷平人，誓将依羽客。","买山构精舍，领徒开讲席。","冀无身外忧，自有闲中益。","道芽期日就，尘虑乃冰释。","且欲遗姓名，安能慕竹帛。","长生尚学致，一溉岂虚掷。","芝术资糇粮，烟霞拂巾帻。","黄石履看堕，洪崖肩可拍。","聊复嗟蜉蝣，何烦哀虺蜴。","青囊既深味，琼葩亦屡摘。","纵无西山资，犹免长戚戚。"],"theme":"游仙梦幻","theme2":["羁旅思乡"],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["山","江","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["写云","太阳"],"人物":["老师"],"人生":["时光","战争"],"植物":["桃花"]},"theme_conf":0.87},{"uid":"a9b365df-54d9-4b2a-b63a-327ecc746a89","title":"杂歌谣辞 渔父歌 二","author":"李珣","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["避世垂纶不记年，官高争得似君闲。","倾白酒，对青山，笑指柴门待月还。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["酒","月","山"],"cats":{"人物":["父亲"]},"theme_conf":0.408},{"uid":"a9b677e8-2657-4d20-9572-1a7479846124","title":"送女子","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青娥宛宛聚为裳，乌鹊桥成别恨长。","惆怅梧桐非旧影，不悲鸿鴈暂随阳。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"惆怅","mood2":["悲怆","愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"人物":["女子"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"aaae5882-9b74-4b45-9bb5-9f773a721119","title":"杂曲歌辞 丽人行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有？翠微㔩叶垂鬓唇。","背后何所见？珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫𫘞之峰出翠釜，水晶之盘行素鳞。","犀筯厌饫久未下，鸾刀缕切空纷纶。","黄门飞鞚不动尘，御厨丝络送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"theme":"讽喻刺世","theme2":["讽喻刺世"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["悲怆"],"scene":["雪","春","花"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.95},{"uid":"2247b3d2-8476-4f8a-be6e-d3f8276751d3","title":"忆杭州梅花因叙旧游寄萧协律","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三年闲闷在余杭，曾为梅花醉几场。","伍相庙边繁似雪，孤山园里丽如妆。","蹋随游骑心长惜，折赠佳人手亦香。","赏自初开直至落，欢因小饮便成狂。","薛刘相次埋新垅，沈谢双飞出故乡。","歌伴酒徒零散尽，唯残头白老萧郎。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","孤寂"],"scene":["花","冬","酒"],"cats":{"抒情":["思念","思乡","孤独"],"山水":["西湖"],"人物":["女子"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"22e72306-f41c-4621-a925-83bab7f9d76e","title":"怨情","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["美人卷珠帘，深坐颦蛾眉。","但见泪痕湿，不知心恨谁。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","闺怨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"cp99f30691ef4ed8","title":"汉宫春","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春已归来，看美人头上，袅袅春幡。","无端风雨，未肯收尽馀寒。","年时燕子，料今宵、梦到西园。","浑未办、黄柑荐酒，更传青韭堆盘。","却笑东风从此，便薰梅染柳，更没些闲。","闲时又来镜里，转变朱颜。","清愁不断，问何人、会解连环。","生怕见、花开花落，朝来塞雁先还。"],"theme":"节令风俗","theme2":["闲适隐逸","边塞征战"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"],"生活":["边塞"]},"theme_conf":0.85},{"uid":"9b4f2d56-6df4-4999-a82c-11283529dd51","title":"感遇十二首 一","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兰叶春葳蕤，桂华秋皎洁。","欣欣此生意，自尔为佳节。","谁知林栖者，闻风坐相悦。","草木有本心，何求美人折。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["春","秋"],"cats":{"四季":["春天","秋天"],"人物":["女子"]},"theme_conf":0.509},{"uid":"b0a1ab7c-8206-4c5c-b333-d5410c429a19","title":"徐卿二子歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见徐卿二子生绝奇，感应吉梦相追随。","孔子释氏亲抱送，竝是天上麒麟儿。","大儿九龄色清澈，秋水为神玉为骨。","小儿五岁气食牛，满堂宾客皆回头。","吾知徐公百不忧，积善衮衮生公侯。","丈夫生儿有如此二雏者，名位岂肯悲微休。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"慷慨","mood2":["相思","悲怆"],"scene":["秋"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.617},{"uid":"e1fea3c2-af73-4b77-8cd1-ebf233140999","title":"从驿次草堂复至东屯二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["短景难高卧，衰年强此身。","山家蒸栗暖，野饭射麋新。","世路知交薄，门庭畏客频。","牧童斯在眼，田父实为邻。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山","园林"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"82a70b6e-d6a8-4155-a043-64664ff6a496","title":"杂歌谣辞 渔父歌 一","author":"李珣","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["水接衡门十里余，信船归去卧看书。","轻爵禄，慕玄虚，莫道渔人只为鱼。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟"],"cats":{"人物":["父亲"]},"theme_conf":0.655},{"uid":"3e971330-6463-4711-83aa-1d0da96589e1","title":"王夫子","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["王夫子，送君为一尉，东南三千五百里。","道途虽远位虽卑，月俸犹堪活妻子。","男儿口读古人书，束带敛手来从事。","近将徇禄给一家，远则行道佐时理。","行道佐时须待命，委身下位无为耻。","命苟未来且求食，官无卑高及远迩。","男儿上既未能济天下，下又不至饥寒死。","吾观九品至一品，其间气味都相似。","紫绶朱绂青布衫，颜色不同而已矣。","王夫子，别有一事欲劝君，遇酒逢春且欢喜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["惆怅"],"scene":["酒","春"],"cats":{"抒情":["离别"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.749},{"uid":"a456cc8d-2cd1-41c9-9cc8-52163216510d","title":"西江上送渔父","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["却逐严光向若耶，钓轮菱櫂寄年华。","三秋梅雨愁枫叶，一夜篷舟宿苇花。","不见水云应有梦，偶随鸥鹭便成家。","白苹风起楼船暮，江燕双双五两斜。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","舟","秋"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"山水":["江河"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"d40a3095-f2e8-4ee3-9f18-b8dba56e4131","title":"赠比部萧郎中十兄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有美生人杰，由来积德门。","汉朝丞相系，梁日帝王孙。","蕴藉为郎久，魁梧秉哲尊。","词华倾后辈，风雅蔼孤骞。","宅相荣姻戚，儿童惠讨论。","见知真自幼，谋拙丑诸昆。","漂荡云天阔，沈埋日月奔。","致君时已晚，怀古意空存。","中散山阳锻，愚公野谷村。","宁纡长者辙，归老任乾坤。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独","怀古"],"人物":["儿童"]},"theme_conf":0.86},{"uid":"051a3fc4-b7c9-4345-a255-2e7887b448e5","title":"相和歌辞 子夜四时歌四首 春歌","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["山连翠羽屏，草接烟华席。","望尽南飞燕，佳人断信息。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.92},{"uid":"3c1693fc-f4e6-43b7-a66f-6379c3a26eef","title":"长相思","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井阑。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有渌水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"449c81fd-d52a-40f2-ae8c-9d3fc5ddd290","title":"牵牛织女","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["牵牛出河西，织女处其东。","万古永相望，七夕谁见同。","神光意难候，此事终蒙胧。","飒然精灵合，何必秋遂通。","亭亭新妆立，龙驾具曾空。","世人亦为尔，祈请走儿童。","称家随丰俭，白屋达公宫。","膳夫翊堂殿，鸣玉凄房栊。","曝衣徧天下，曳月扬微风。","蛛丝小人态，曲缀瓜果中。","初筵裛重露，日出甘所终。","嗟汝未嫁女，秉心郁忡忡。","防身动如律，竭力机杼中。","虽无姑舅事，敢昧织作功。","明明君臣契，咫尺或未容。","义无弃礼法，恩始夫妇恭。","小大有佳期，戒之在至公。","方圆苟龃龉，丈夫多英雄。"],"theme":"节令风俗","theme2":["民生疾苦"],"style":"豪放","style2":["清新","旷达"],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"天气":["星星"],"人物":["儿童"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"a65310a3-4f4a-4b39-bbd4-1c751654ac39","title":"奉和李大夫题新诗二首各六韵 忘筌亭","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翠𪩘公门对，朱轩野径连。","只开新户牖，不改旧风烟。","虚室闲生白，高情澹入玄。","酒容同座劝，诗借属城传。","自笑沧江畔，遥思绛帐前。","亭台随处有，争敢比忘筌。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["豪放","冲淡"],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"人物":["老师"]},"theme_conf":0.88},{"uid":"b59e2948-4c90-4b33-8af6-d02b79efd5fd","title":"彭衙行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔避贼初，北走经险艰。","夜深彭衙道，月照白水山。","尽室久徒步，逢人多厚颜。","参差谷鸟吟，不见游子还。","痴女饥𫜪我，啼畏虎狼闻。","怀中掩其口，反侧声愈嗔。","小儿强解事，故索苦李餐。","一旬半雷雨，泥泞相牵攀。","既无御雨备，径滑衣又寒。","有时经契阔，竟日数里间。","野果充糇粮，卑枝成屋椽。","早行石上水，暮宿天边烟。","少留周家洼，欲出芦子关。","故人有孙宰，高义薄曾云。","延客已曛黑，张灯启重门。","煖汤濯我足，剪纸招我魂。","从此出妻孥，相视涕阑干。","众雏烂熳睡，唤起沾盘餐。","誓将与夫子，永结为弟昆。","遂空所坐堂，安居奉我欢。","谁肯艰难际，豁达露心肝。","别来岁月周，胡羯仍搆患。","何当有翅翎，飞去堕尔前。"],"theme":"寄赠酬答","theme2":["送别","民生疾苦","山水田园"],"style":"幽峭","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["夜","月","雨"],"cats":{"抒情":["友情","思念"],"人物":["儿童"]},"theme_conf":0.82},{"uid":"87589e47-69eb-4b30-8204-5678cb0c8636","title":"游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故窠思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰归百年内，唯愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何难哉，北斗不可斟。","夜静星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蟋蟋催寒碪。","立身计几悮，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧罔古今。","胡为不归欤，辜负匣中琴。","腰下是何物，牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山窅岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾宵汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分湮沈。","层城登云韶，王府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"恬淡","mood2":["愁怨","悲怆"],"scene":["秋","江","月","夜","鸟"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.292},{"uid":"2e99fd87-77f9-42d7-af47-1a845e2e865d","title":"渔父歌 三","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["霅谿湾里钓渔翁，舴艋为家西复东。","江上雪，浦边风，笑著荷衣不叹穷。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","江"],"cats":{"人物":["父亲"]},"theme_conf":0.742},{"uid":"f61de6f0-8b47-4b5f-8344-b95849bd556d","title":"鼓吹曲辞 有所思","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["君子事行役，再空芳岁期。","美人旷延伫，万里浮云思。","园槿绽红艳，郊桑柔绿滋。","坐看长夏晚，秋月生罗帏。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约","豪放"],"mood":"相思","mood2":[],"scene":["夏","花","秋","月","园林"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"],"人物":["女子"]},"theme_conf":0.524},{"uid":"da7e5017-c5ed-43a9-9400-e1a77958aa19","title":"送李栖桐道举擢第还乡省侍","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["几年深道要，一举过贤关。","名与玄珠出，乡宜昼锦还。","莲舟同宿浦，柳岸向家山。","欲见宁亲孝，儒衣稚子斑。"],"theme":"羁旅思乡","theme2":["送别"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["舟","山"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.474},{"uid":"2161a569-6250-4886-9500-2168821b62be","title":"瑶池","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["瑶池阿母绮窗开，黄竹歌声动地哀。","八骏日行三万里，穆王何事不重来。"],"theme":"讽喻刺世","theme2":["游仙梦幻"],"style":"豪放","style2":["绮丽","悲慨"],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"人物":["母亲"]},"theme_conf":0.588},{"uid":"80e19627-4051-46fc-806c-da3defb76cd1","title":"陪王侍御同登东山最高顶宴姚通泉晚携酒泛江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姚公美政谁与俦，不减昔时陈太丘。","邑中上客有柱史，多暇日陪骢马游。","东山高顶罗珍羞，下顾城郭销我忧。","清江白日落欲尽，复携美人登彩舟。","笛声愤怨哀中流，妙舞逶迤夜未休。","灯前往往大鱼出，听曲低昂如有求。","三更风起寒浪涌，取乐喧呼觉船重。","满空星河光破碎，四座宾客色不动。","请公临深莫相违，回船罢酒上马归。","人生欢会岂有极，无使霜过沾人衣。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","酒","山","江","舟"],"cats":{"山水":["江河"],"天气":["星星"],"人物":["女子"],"食物":["写酒"]},"theme_conf":0.407},{"uid":"a8e39b30-119d-4b4f-b557-da792950a2a3","title":"杂曲歌辞 行路难三首 三","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["飞雪断道冰成梁，侯家炽炭雕玉房。","蟠龙吐耀虎喙张，熊蹲豹掷争低昂。","攒峦丛崿射朱光，丹霞翠雾飘奇香。","美人四向回明珰，雪山冰谷晞太阳。","星躔奔走不得止，奄忽双燕栖虹梁。","风台露榭生光饰，死灰弃置参与商。","盛时一去贵反贱，桃笙葵扇安可常。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思乡"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"29005e2b-3311-40df-a3b8-5ff8455bc4af","title":"渔父歌 四","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["松江蟹舍主人欢，菰饭莼羹亦共餐。","枫叶落，荻花干，醉宿渔舟不觉寒。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["舟","江","酒"],"cats":{"人物":["父亲"]},"theme_conf":0.687},{"uid":"d719fd0e-bbf4-49b5-83f7-e04ad1d1b9d3","title":"春日送沈赞府归浔阳觐叔父","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浔阳阮咸宅，九派竹林前。","花屿高如浪，云峰远似天。","江声在南巷，海气入东田。","才子今朝去，风涛思渺然。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["父亲"]},"theme_conf":0.536},{"uid":"3678278c-bddf-4639-837c-45fa64d6b28b","title":"自阆州领妻子却赴蜀州山行三首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["行色递隐见，人烟时有无。","仆夫穿竹语，稚子入云呼。","转石惊魑魅，抨弓落狖鼯。","真供一笑乐，似欲慰穷途。"],"theme":"山水田园","theme2":["亲情","边塞征战"],"style":"旷达","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"人物":["儿童"]},"theme_conf":0.431},{"uid":"4a9c46cb-b60d-439c-885e-c4dc8522940f","title":"送顾况泗上觐叔父","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["吴乡岁贡足嘉宾，后进之中见此人。","别业更临洙泗上，拟将书卷对残春。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","江南"],"cats":{"四季":["春天"],"人物":["父亲"],"人生":["读书"]},"theme_conf":0.671},{"uid":"9d974ae6-2223-4fa3-bb66-15a079adec68","title":"送孔巢父赴河南军","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江城相送阻烟波，况复新秋一雁过。","闻道全师征北虏，更言诸将会南河。","边心杳杳乡人绝，塞草青青战马多。","共许陈琳工奏记，知君名宦未蹉跎。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","塞外","秋"],"cats":{"四季":["秋天"],"山水":["江河"],"人物":["父亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"da21588d-5e04-4707-a084-696ba5120669","title":"茶山下作","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春风最窈窕，日晓柳村西。","娇云光占岫，健水鸣分溪。","燎岩野花远，戛瑟幽鸟啼。","把酒坐芳草，亦有佳人携。"],"theme":"山水田园","theme2":["山水田园"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"人物":["女子"],"食物":["写茶"]},"theme_conf":0.92},{"uid":"b27218c9-b467-43e7-b625-9513fc7c6044","title":"病后寒食","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故纱绛帐旧青毡，药酒醺醺引醉眠。","斗擞弊袍春晚后，摩挲病脚日阳前。","行无筋力寻山水，坐少精神听管弦。","抛掷风光负寒食，曾来未省似今年。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"人物":["老师"],"节日":["寒食节","清明节"]},"theme_conf":0.76},{"uid":"d8d4a2e2-28ae-42d1-84ce-306a9b4df039","title":"听唱赤白桃李花","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["赤白桃李花，先皇在时曲。","欲向西宫唱，西宫[宫]树绿。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.7},{"uid":"47dbfc92-dd51-458f-859a-1953cde28460","title":"秋日作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居值秋节，此日更愁辛。","寂寞无一事，蒿莱通四邻。","闭门生白发，回首忆青春。","岁月不相待，交游随众人。","云霄何处托，愚直有谁亲。","举酒聊自劝，穷通信尔身。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["秋"],"cats":{"抒情":["思念","伤感","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"人生":["青春"]},"theme_conf":0.9},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"f0dc1b19-1846-4837-937f-8c2ff37fcd18","title":"杂曲歌辞 长相思三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["美人在时花满堂，美人去后花余床。","床中绣被卷不寝，至今三载犹闻香。","香亦竟不灭，人亦竟不来。","相思黄叶落，白露点青苔。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","思念"],"人物":["女子"]},"theme_conf":0.77},{"uid":"e05b6908-5d87-4a15-b58b-54fd0c59c00e","title":"旅次汉故畤","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我行过汉畤，寥落见孤城。","邑里经多难，儿童识五兵。","广川桑遍绿，丛薄雉连鸣。","惆怅萧关道，终军愿请缨。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["慷慨","孤寂"],"scene":[],"cats":{"抒情":["思乡","孤独","爱国"],"人物":["儿童"]},"theme_conf":0.632},{"uid":"6f50b001-74c4-4c85-a2a3-626560010c86","title":"长安客舍赠李行父明府","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["藏器待时少，知人自古难。","遂令丹穴凤，晚食金琅玕。","谁谓兵戈际，鸣琴方一弹。","理烦善用简，济猛能兼宽。","夙夜念黎庶，寝兴非宴安。","洪波未静壑，何树不惊鸾。","凫舄傍京辇，甿心悬灌坛。","高槐暗苦雨，长剑生秋寒。","旅食还为客，饥年亦尽欢。","亲劳携斗水，往往救泥蟠。","但恐酬明义，蹉跎芳岁阑。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["秋","夜","山","雨"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"1ab8a232-27bf-4de3-b67c-28e4735fea7f","title":"横吹曲辞 长安道","author":"韦应物","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家宫殿含云烟，两宫十里相连延。","晨霞出没弄丹阙，春雨依微自甘泉。","春雨依微春尚早，长安贵游爱芳草。","宝马横来下建章，香车却转避驰道。","贵游谁最贵，卫霍世难比。","何能蒙主恩？幸遇边尘起。","归来甲第拱皇居，朱门峨峨临九衢。","中有流苏合欢之宝帐，一百二十凤皇罗列含明珠。","下有锦铺翠被之粲烂，博山吐香五云散。","丽人绮阁情飘飖，头上鸳钗双翠翘。","低鬟曳袖回春雪，聚黛一声愁碧霄。","山珍海错弃藩篱，烹犊炰羔如折葵。","既请列侯封部曲，还将金印授庐儿。","欢荣若此何所苦，但苦白日西南驰。"],"theme":"山水田园","theme2":["闺情宫怨","讽喻刺世"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春","花","雪","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.429},{"uid":"9c5c45b3-3e85-4eeb-b9de-eba380e530b6","title":"杂歌谣辞 渔父歌 一","author":"张志和","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西塞山边白鹭飞，桃花流水鳜鱼肥。","青箬笠，绿蓑衣，春江细雨不须归。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["雨","塞外"],"cats":{"天气":["写雨"],"人物":["父亲"]},"theme_conf":0.642},{"uid":"18801489-9f1d-4d5d-9618-66e682d3fc54","title":"寄司空曙","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["细雨柴门生远愁，向来诗句若为酬。","林花落处频中酒，海燕飞时独倚楼。","北郭晚晴山更远，南塘春尽水争流。","可能相别还相忆，莫遣杨花笑白头。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["老师"]},"theme_conf":0.92},{"uid":"98837307-06dd-4453-a57b-92fe56040323","title":"赠成炼师四首 四","author":"刘言史","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曾随阿母汉宫斋，凤驾龙𫐌列玉堦。","当时白燕无寻处，今日云鬟见玉钗。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":0.84},{"uid":"cpcf88bc5d6261e8","title":"苏武慢","author":"蔡伸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["雁落平沙，烟笼寒水，古垒鸣笳声断。","青山隐隐，败叶萧萧，天际暝鸦零乱。","楼上黄昏，片帆千里归程，年华将晚。","望碧云空暮，佳人何处，梦魂俱远。","忆旧游、邃馆朱扉，小园香径，尚想桃花人面。","书盈锦轴，恨满金徽，难写寸心幽怨。","两地离愁，一尊芳酒，凄凉危阑倚遍。","尽迟留、凭仗西风，吹干泪眼。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","鸟","酒"],"cats":{"抒情":["思乡","伤感"],"人物":["女子"]},"theme_conf":0.51},{"uid":"80f35550-53c7-4dd4-a386-0710a32fd153","title":"题温处士山居","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁知白云外，别有绿萝春。","苔绕溪边径，花深洞里人。","逸妻看种药，稚子伴垂纶。","颍上逃尧者，何如此养真。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春"],"cats":{"四季":["春天"],"人物":["儿童"]},"theme_conf":0.382},{"uid":"4af04ec2-4fde-4a22-8847-3ee2dcb3f527","title":"微之到通州日授馆未安见尘壁间有数行字读之即仆旧诗其落句云渌水红莲一朵开千花百草无颜色然不知题者何人也微之吟叹不足因缀一章兼录仆诗本同寄省其诗乃十五年前初及第时赠长安妓人阿輭绝句缅思往事杳若梦中怀旧感今因酬长句","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十五年前似梦游，曾将诗句结风流。","偶助笑歌嘲阿輭，可知传诵到通州。","昔教红袖佳人唱，今遣青衫司马愁。","惆怅又闻题处所，雨淋江馆破墙头。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["花"],"cats":{"人物":["女子"],"人生":["梦想"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"773e3420-7888-4c61-b026-fad74cf8a313","title":"假龙吟歌","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石轧铜杯，吟咏枯瘁。","苍鹰摆血，白凤下肺。","桂子自落，云弄车盖。","木死沙崩恶谿岛，阿母得仙今不老。","窞中跳汰截清涎，隈壖卧水埋金爪。","崖蹬苍苔吊石发，江君掩帐筼筜折。","莲花去国一千年，雨后闻腥犹带铁。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["雄浑"],"mood":"悲怆","mood2":[],"scene":["雨"],"cats":{"人物":["母亲"]},"theme_conf":0.65},{"uid":"396cd474-fdac-49f4-9594-f28d013760ac","title":"杂歌谣辞 郑樱桃歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","春","七夕"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"节日":["七夕节"],"植物":["桃花"]},"theme_conf":0.581},{"uid":"cp9c6ef11cc870d5","title":"浪淘沙","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["梦觉、透窗风一线，寒灯吹息。","那堪酒醒，又闻空阶，夜雨频滴。","嗟因循、久作天涯客。","负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。","愁极。","再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。","云尤雨，有万般千种，相怜相惜。","恰到如今，天长漏永，无端自家疏隔。","知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["冲淡"],"mood":"愁怨","mood2":["相思"],"scene":["夜"],"cats":{"抒情":["思念","思乡","伤感"],"人物":["女子"]},"theme_conf":0.765},{"uid":"e1ea09bb-0ca8-4ec2-b9ee-f1299f878734","title":"游后湖赏莲花","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["蓼花蘸水火不灭，水鸟惊鱼银梭投。","满目荷花千万顷，红碧相杂敷清流。","孙武已斩吴宫女，琉璃池上佳人头。"],"theme":"山水田园","theme2":["咏史怀古","闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["花","江"],"cats":{"抒情":["闺怨","怀古"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.354},{"uid":"3e9f5dd2-0524-495f-8a52-94212ad97ed4","title":"谁氏子","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["非痴非狂谁氏子，去入王屋称道士。","白头老母遮门啼，挽断衫袖留不止。","翠眉新妇年二十，载送还家哭穿市。","或云欲学吹凤笙，所慕灵妃嫓萧史。","又云时俗轻寻常，力行险怪取贵仕。","神僊虽然有传说，知者尽知其妄矣。","圣君贤相安可欺，干死穷山竟何俟。","呜呼余心诚岂弟，愿往教诲究终始。","罚一劝百政之经，不从而诛未晚耳。","谁其友亲能哀怜，写吾此诗持送似。"],"theme":"讽喻刺世","theme2":["送别"],"style":"沉郁","style2":["幽峭","婉约"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"人物":["母亲"]},"theme_conf":0.9},{"uid":"f8071036-9e39-49c2-b3e9-09fdeb4a5f82","title":"同州端午","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹤发垂肩尺许长，离家三十五端阳。","儿童见说深惊讶，却问何方是故乡。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"dfc0cb68-548a-41aa-a47f-492d7e264183","title":"琴曲歌辞 琴歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["琴调秋些，胡风遶雪。","峡泉生咽，佳人愁些。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.628},{"uid":"d1734c10-cff7-42c7-8763-0b04378a3864","title":"感石榴二十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何年安石国，万里贡榴花。","迢递河源道，因依汉使槎。","酸辛犯葱岭，顦顇涉龙沙。","初到摽珍木，多来比乱麻。","深抛故园里，少种贵人家。","唯我荆州见，怜君胡地赊。","从教当路长，兼恣入檐斜。","绿叶裁烟翠，红英动日华。","新帘帬透影，疎牖烛笼纱。","委作金炉燄，飘成玉砌瑕。","乍惊珠缀密，终误绣帏奢。","琥珀烘梳碎，燕支嬾颊涂。","风翻一树火，电转五云车。","绛帐迎宵日，芙蕖绽早牙。","浅深俱隐映，前后各分葩。","宿露低莲脸，朝光借绮霞。","暗虹徒缴绕，濯锦莫周遮。","俗态能嫌旧，芳姿尚可嘉。","非专爱颜色，同恨阻幽遐。","满眼思乡泪，相嗟亦自嗟。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","园林"],"cats":{"抒情":["思乡","伤感"],"山水":["黄河"],"人物":["老师"]},"theme_conf":0.504},{"uid":"cpa13dd8628ea1d7","title":"虞美人","author":"舒亶","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芙蓉落尽天涵水。","日暮沧波起。","背飞双燕帖云寒。","独向小楼东畔、倚阑看。","浮生只合尊前老。","雪满长安道。","故人早晚上高台。","赠我江南春色、一枝梅。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江南","冬","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"1a55ca5a-de6c-4286-90a0-e57ed2adfeec","title":"走笔追王内丘","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自识夫子面，便获夫子心。","夫子一启颜，义重千黄金。","平原孟尝骨已土，始有夫子堪知音。","忽然夫子不语，带席帽，骑驴去。","余对醁醽不能斟，君且来，余之瞻望心悠哉。","零雨其蒙愁不散，闲花寂寂斑堦苔。","不如对此景，含笑倾金罍。","莫问四肢畅，暂取眉头开。","弦琴待夫子，夫子来不来。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","愁怨"],"scene":["雨"],"cats":{"抒情":["友情","伤感"],"人物":["老师"]},"theme_conf":0.82},{"uid":"2f6e3b2d-dc26-4be1-bf64-0710c7eaa7cd","title":"相和歌辞 铜雀妓","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳人一壶酒，秋容满千里。","石马卧新烟，忧来何所似？","歌声且潜弄，陵树风自起。","长裾压高台，泪眼看花机。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"cp03094b5525f32e","title":"宝鼎现","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["红妆春骑。","踏月影、竿旗穿市。","望不尽、楼台歌舞，习习香尘莲步底。","箫声断、约彩鸾归去，未怕金吾呵醉。","甚辇路、喧阗且止。","听得念奴歌起。","父老犹记宣和事。","抱铜仙、清泪如水。","还转盼、沙河多丽。","漾明光连邸第。","帘影冻、散红光成绮。","月浸葡萄十里。","看往来、神仙才子。","肯把菱花扑碎。","肠断竹马儿童，空见说、三千乐指。","等多时春不归来，到春时欲睡。","又说向、灯前拥髻。","暗滴鲛珠坠。","便当日、亲见霓裳，天上人间梦里。"],"theme":"闺情宫怨","theme2":["山水田园","民生疾苦"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["花","楼","春","月"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.405},{"uid":"997b631a-bfdd-40d0-9142-69a887e1092e","title":"和吴中丞悼笙妓","author":"李群玉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["丽质仙姿烟逐风，凤皇声断吹台空。","多情草色怨还绿，无主杏花春自红。","堕珥尚存芳树下，余香渐减玉堂中。","唯应去抱云和管，从此长归阿母宫。"],"theme":"悼亡挽歌","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","江南"],"cats":{"抒情":["悼亡"],"人物":["母亲"]},"theme_conf":0.94},{"uid":"dd5f08ab-e872-48df-978b-369433e46e7d","title":"同诸子哭张元易","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["盛德高名总是空，神明福善大朦胧。","游魂永永无归日，流水年年自向东。","素帷旅榇乡关远，丹旐孤灯客舍中。","伯道共悲无后嗣，孀妻老母断根蓬。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"沉郁","style2":["冲淡"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感","悼亡"],"人物":["母亲"]},"theme_conf":0.521},{"uid":"08dc6c3a-07bc-479a-9bbe-4225ff0352e6","title":"忆幼子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骥子春犹隔，莺歌暖正繁。","别离惊节换，聪慧与谁论。","涧水空山道，柴门老树村。","忆渠愁只睡，炙背俯晴轩。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.638},{"uid":"23b288e3-01d9-4688-8f00-8572431a2819","title":"同乐天和微之深春二十首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何处深春好，春深阿母家。","瑶池长不夜，珠树正开花。","桥峻通星渚，楼暄近日车。","层城十二阙，相对日西斜。"],"theme":"亲情","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"0f5d3f4a-dbf2-4831-b658-e75bd4a0ca38","title":"羌村 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晚岁迫偷生，还家少欢趣。","娇儿不离膝，畏我复却去。","忆昔好追凉，故绕池边树。","萧萧北风劲，抚事煎百虑。","赖知禾黍收，已觉糟床注。","如今足斟酌，且用慰迟暮。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["酒"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.405},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"6038ff33-cb0f-4ab7-82bd-c603b030c1bb","title":"伤歙州陈二使君","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怜君辞满卧沧洲，一旦云亡万事休。","慈母断肠妻独泣，寒云惨色水空流。","江村故老长怀惠，山路孤猨亦共愁。","寂寞荒坟近渔浦，野松孤月即千秋。"],"theme":"悼亡挽歌","theme2":["山水田园","亲情"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["江","秋","月"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["秋天"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"81c77b01-47cd-4aba-a980-5bc74b5b9711","title":"狂夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万里桥西一，草堂，百花潭水即沧浪。","风含翠筿娟娟静，雨裛红蕖冉冉香。","厚禄故人书断绝，恒饥稚子色凄凉。","欲填沟壑唯疎放，自笑狂夫老更狂。"],"theme":"民生疾苦","theme2":["亲情"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["花","雨","山"],"cats":{"抒情":["伤感"],"人物":["儿童"],"生活":["写桥"]},"theme_conf":0.49},{"uid":"3d5cbb39-2531-4c18-b45e-fe6af04c857e","title":"东都父老望幸","author":"薛存诚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["銮舆秦地久，羽卫洛阳空。","彼土虽凭固，兹川乃得中。","龙颜觐白日，鹤发仰清风。","望幸诚逾邈，怀来意不穷。","昔因封泰岳，今伫蹑维嵩。","天地心无异，神祇理亦同。","翠华翔渭北，玉检候关东。","众愿其难阻，明君早勒功。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["闺怨"],"人物":["父亲"]},"theme_conf":0.623},{"uid":"cp194ecb5ec04420","title":"迷神引","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一叶扁舟轻帆卷。","暂泊楚江南岸。","孤城暮角，引胡茄怨。","水茫茫，平沙雁、旋惊散。","烟敛寒林簇，画屏展。","天际遥山小，黛眉浅。","旧赏轻抛，到此成游宦。","觉客程劳，年光晚。","异乡风物，忍萧索、当愁眼。","帝城赊，秦楼阻，旅魂乱。","芳草连空阔，残照满。","佳人无消息，断云远。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["舟"],"cats":{"抒情":["思乡","伤感","孤独"],"人物":["女子"]},"theme_conf":0.601},{"uid":"bd3a0a24-fd2c-4aa9-86d9-ff08f158bb61","title":"宿诚禅师山房题赠二首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宴坐白云端，清江直下看。","来人望金刹，讲席绕香坛。","虎啸夜林动，鼍鸣秋涧寒。","众音徒起灭，心在净中观。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["山","秋","夜"],"cats":{"四季":["秋天"],"人物":["老师"],"人生":["哲理"]},"theme_conf":0.442},{"uid":"33789ba7-a44a-4989-9da1-f1379968bb8a","title":"饮后戏示弟子","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾为尔先生，尔为吾弟子。","孔门有遗训，复坐吾告尔。","先生馔酒食，弟子服劳止。","孝敬不在他，在兹而已矣。","欲我少忧愁，欲我多欢喜。","无如酝好酒，酒须多且旨。","旨即宾可留，多即罍不耻。","吾更有一言，尔宜听入耳。","人老多忧贫，人病多忧死。","我今虽老病，所忧不在此。","忧在半酣时，尊空座客起。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["欢愉"],"scene":["酒"],"cats":{"抒情":["思乡","伤感"],"人物":["老师"]},"theme_conf":0.65},{"uid":"768287b6-de28-4e1a-90b7-b1446f1dca99","title":"病中辱崔宣城长句见寄兼有觥绮之赠因以四韵总而酬之","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["刘[桢]病发经春卧，谢朓诗来尽日吟。","三道旧夸收片玉，一章新喜获双金。","信题霞绮缄情重，酒试银觥表分深。","科第门生满霄汉，岁寒少得似君心。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["春","酒","冬"],"cats":{"四季":["春天","冬天"],"人物":["老师"]},"theme_conf":0.98},{"uid":"370b53ae-949e-45cf-92b0-3aca072c1b86","title":"丽人行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三月三日天气新，长安水边多丽人。","态浓意远淑且真，肌理细腻骨肉匀。","绣罗衣裳照暮春，蹙金孔雀银麒麟。","头上何所有，翠微㔩叶垂鬓唇。","背后何所见，珠压腰衱稳称身。","就中云幕椒房亲，赐名大国虢与秦。","紫驼之峰出翠釜，水精之盘行素鳞。","犀箸厌饫久未下，銮刀缕切空纷纶。","黄门飞鞚不动尘，御厨络绎送八珍。","箫鼓哀吟感鬼神，宾从杂遝实要津。","后来鞍马何逡巡，当轩下马入锦茵。","杨花雪落覆白苹，青鸟飞去衔红巾。","炙手可热势绝伦，慎莫近前丞相嗔。"],"theme":"讽喻刺世","theme2":["讽喻刺世"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["悲怆"],"scene":["雪","春","花"],"cats":{"四季":["春天"],"人物":["女子"]},"theme_conf":0.95},{"uid":"8138a2d0-cd03-4430-95cf-487daa5d6902","title":"将赴成都草堂途中有作先寄严郑公五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["处处青江带白苹，故园犹得见残春。","雪山斥候无兵马，锦里逢迎有主人。","休怪儿童延俗客，不教鹅鸭恼比邻。","习池未觉风流尽，况复旌州赏更新。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["园林","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.95},{"uid":"c6bcc594-fe63-4aa7-8d76-3a15d7fba078","title":"赠郑夫子鲂","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天地入胸臆，吁嗟生风雷。","文章得其微，物象由我裁。","宋玉逞大句，李白飞狂才。","苟非圣贤心，孰与造化该。","勉矣郑夫子，骊珠今始胎。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":[],"cats":{"人物":["老师"]},"theme_conf":0.72},{"uid":"1e3e6d44-452e-4d2a-a4ef-1432ea95da22","title":"舞曲歌辞 白纻辞三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["扬清歌，发皓齿，北方佳人东邻子。","且吟白纻停渌水，长袖拂面为君起。","寒云夜卷霜海空，胡风吹天飘塞鸿。","玉颜满堂乐未终，馆娃日落歌吹蒙。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","夜"],"cats":{"人物":["女子"],"生活":["边塞"]},"theme_conf":1.0}];
